32	struct WsEndpoint
33	{
34	    std::string host;
35	    std::string port;
36	    std::string target;
37	    bool        secure = false;
38	};
39	
40	bool parse_ws_endpoint(const std::string& base_url, WsEndpoint& endpoint)
41	{
42	    if (base_url.empty()) {
43	        return false;
44	    }
45	
46	    std::string url = base_url;
47	    if (boost::istarts_with(url, "https://")) {
48	        endpoint.secure = true;
49	        url             = url.substr(8);
50	    } else if (boost::istarts_with(url, "http://")) {
51	        url = url.substr(7);
52	    }
53	
54	    auto slash = url.find('/');
55	    if (slash != std::string::npos) {
56	        url = url.substr(0, slash);
57	    }
58	    if (url.empty()) {
59	        return false;
60	    }
61	
62	    endpoint.host = url;
63	    endpoint.port = endpoint.secure ? "443" : "80";
64	    if (auto colon = url.rfind(':'); colon != std::string::npos && url.find(']') == std::string::npos) {
65	        endpoint.host = url.substr(0, colon);
66	        endpoint.port = url.substr(colon + 1);
67	    }
68	
69	    endpoint.target = "/websocket";
70	    return !endpoint.host.empty() && !endpoint.port.empty();
71	}
