73	std::string map_moonraker_state(std::string state)
74	{
75	    boost::algorithm::to_lower(state);
76	    if (state == "printing") {
77	        return "RUNNING";
78	    }
79	    if (state == "paused") {
80	        return "PAUSE";
81	    }
82	    if (state == "complete") {
83	        return "FINISH";
84	    }
85	    if (state == "error" || state == "cancelled") {
86	        return "FAILED";
87	    }
88	    return "IDLE";
89	}
