137	int MoonrakerPrinterAgent::connect_printer(std::string dev_id, std::string dev_ip, std::string username, std::string password, bool use_ssl)
138	{
139	    if (dev_id.empty() || dev_ip.empty()) {
140	        BOOST_LOG_TRIVIAL(error) << "MoonrakerPrinterAgent: connect_printer missing dev_id or dev_ip";
141	        return BAMBU_NETWORK_ERR_INVALID_HANDLE;
142	    }
143	
144	    std::string base_url;
145	    std::string api_key;
146	    uint64_t gen;
147	    {
148	        std::lock_guard<std::recursive_mutex> lock(connect_mutex);
149	        init_device_info(dev_id, dev_ip, username, password, use_ssl);
150	        gen = ++connect_generation;
151	        base_url = device_info.base_url;
152	        api_key  = device_info.api_key;
153	        if (connect_thread.joinable()) {
154	            connect_thread.detach();
155	        }
156	    }
157	
158	    // Stop existing status stream and clear state
159	    stop_status_stream();
160	    {
161	        std::lock_guard<std::recursive_mutex> lock(payload_mutex);
162	        status_cache = nlohmann::json::object();
163	    }
164	    ws_last_emit_ms.store(0);
165	    ws_last_dispatch_ms.store(0);
166	    last_print_state.clear();
167	
168	    // Launch connection in background thread (capture by value to avoid data races)
169	    {
170	        std::lock_guard<std::recursive_mutex> lock(connect_mutex);
171	        connect_thread = std::thread([this, dev_id, base_url, api_key, gen]() { perform_connection_async(dev_id, base_url, api_key, gen); });
172	    }
173	
174	    return BAMBU_NETWORK_SUCCESS;
175	}
