297	int MoonrakerPrinterAgent::start_send_gcode_to_sdcard(PrintParams      params,
298	                                                      OnUpdateStatusFn update_fn,
299	                                                      WasCancelledFn   cancel_fn,
300	                                                      OnWaitFn         wait_fn)
301	{
302	    (void) wait_fn;
303	
304	    if (update_fn)
305	        update_fn(PrintingStageCreate, 0, "Preparing...");
306	
307	    std::string filename = params.filename;
308	    if (filename.empty()) {
309	        filename = params.task_name;
310	    }
311	    if (!boost::iends_with(filename, ".gcode")) {
312	        filename += ".gcode";
313	    }
314	
315	    // Sanitize filename to prevent path traversal attacks
316	    std::string safe_filename = sanitize_filename(filename);
317	
318	    // Upload only, don't start print
319	    if (!upload_gcode(params.filename, safe_filename, device_info.base_url, device_info.api_key, update_fn, cancel_fn)) {
320	        return BAMBU_NETWORK_ERR_PRINT_SG_UPLOAD_FTP_FAILED;
321	    }
322	
323	    if (update_fn)
324	        update_fn(PrintingStageFinished, 100, "File uploaded");
325	    return BAMBU_NETWORK_SUCCESS;
326	}
