328	int MoonrakerPrinterAgent::start_local_print(PrintParams params, OnUpdateStatusFn update_fn, WasCancelledFn cancel_fn)
329	{
330	    if (update_fn)
331	        update_fn(PrintingStageCreate, 0, "Preparing...");
332	
333	    // Check cancellation
334	    if (cancel_fn && cancel_fn()) {
335	        return BAMBU_NETWORK_ERR_CANCELED;
336	    }
337	    // Determine the G-code file to upload
338	    // params.filename may be .3mf, params.dst_file contains actual G-code
339	    std::string gcode_path = params.filename;
340	    if (!params.dst_file.empty()) {
341	        gcode_path = params.dst_file;
342	    }
343	
344	    // Check if file exists and has .gcode extension
345	    namespace fs = boost::filesystem;
346	    fs::path source_path(gcode_path);
347	    if (!fs::exists(source_path)) {
348	        BOOST_LOG_TRIVIAL(error) << "MoonrakerPrinterAgent: G-code file does not exist: " << gcode_path;
349	        return BAMBU_NETWORK_ERR_FILE_NOT_EXIST;
350	    }
351	
352	    // Extract filename for upload (relative to gcodes root)
353	    std::string upload_filename = source_path.filename().string();
354	    if (!boost::iends_with(upload_filename, ".gcode")) {
355	        upload_filename += ".gcode";
356	    }
357	    // Sanitize filename to prevent path traversal attacks (extra safety)
358	    upload_filename = sanitize_filename(upload_filename);
359	
360	    // Upload file
361	    if (update_fn)
362	        update_fn(PrintingStageUpload, 0, "Uploading G-code...");
363	    if (!upload_gcode(gcode_path, upload_filename, device_info.base_url, device_info.api_key, update_fn, cancel_fn)) {
364	        return BAMBU_NETWORK_ERR_PRINT_LP_UPLOAD_FTP_FAILED;
365	    }
366	
367	    // Check cancellation
368	    if (cancel_fn && cancel_fn()) {
369	        return BAMBU_NETWORK_ERR_CANCELED;
370	    }
371	
372	    // Start print via gcode script (simpler than JSON-RPC)
373	    if (update_fn)
374	        update_fn(PrintingStageSending, 0, "Starting print...");
375	    std::string gcode = "SDCARD_PRINT_FILE FILENAME=" + upload_filename;
376	    if (!send_gcode(device_info.dev_id, gcode)) {
377	        return BAMBU_NETWORK_ERR_PRINT_LP_PUBLISH_MSG_FAILED;
378	    }
379	
380	    if (update_fn)
381	        update_fn(PrintingStageFinished, 100, "Print started");
382	    return BAMBU_NETWORK_SUCCESS;
383	}
