451	void MoonrakerPrinterAgent::build_ams_payload(int ams_count, int max_lane_index, const std::vector<AmsTrayData>& trays)
452	{
453	
454	    // Look up MachineObject via DeviceManager
455	    auto* dev_manager = GUI::wxGetApp().getDeviceManager();
456	    if (!dev_manager) {
457	        return;
458	    }
459	    MachineObject* obj = dev_manager->get_my_machine(device_info.dev_id);
460	    if (!obj) {
461	        return;
462	    }
463	
464	    // Build BBL-format JSON for DevFilaSystemParser::ParseV1_0
465	    nlohmann::json ams_json = nlohmann::json::object();
466	    nlohmann::json ams_array = nlohmann::json::array();
467	
468	    // Calculate ams_exist_bits and tray_exist_bits
469	    unsigned long ams_exist_bits = 0;
470	    unsigned long tray_exist_bits = 0;
471	
472	    for (int ams_id = 0; ams_id < ams_count; ++ams_id) {
473	        ams_exist_bits |= (1 << ams_id);
474	
475	        nlohmann::json ams_unit = nlohmann::json::object();
476	        ams_unit["id"] = std::to_string(ams_id);
477	        ams_unit["info"] = "0002";  // treat as AMS_LITE 
478	
479	        nlohmann::json tray_array = nlohmann::json::array();
480	        int max_slot_in_this_ams = std::min(3, max_lane_index - ams_id * 4);
481	        for (int slot_id = 0; slot_id <= max_slot_in_this_ams; ++slot_id) {
482	            int slot_index = ams_id * 4 + slot_id;
483	
484	            // Find tray with matching slot_index
485	            const AmsTrayData* tray = nullptr;
486	            for (const auto& t : trays) {
487	                if (t.slot_index == slot_index) {
488	                    tray = &t;
489	                    break;
490	                }
491	            }
492	
493	            nlohmann::json tray_json = nlohmann::json::object();
494	            tray_json["id"] = std::to_string(slot_id);
495	            tray_json["tag_uid"] = "0000000000000000";
496	
497	            if (tray && tray->has_filament) {
498	                tray_exist_bits |= (1 << slot_index);
499	
500	                tray_json["tray_info_idx"] = tray->tray_info_idx;
501	                tray_json["tray_type"] = tray->tray_type;
502	                tray_json["tray_color"] = normalize_color_value(tray->tray_color);
503	
504	                // Add temperature data if provided
505	                if (tray->bed_temp > 0) {
506	                    tray_json["bed_temp"] = std::to_string(tray->bed_temp);
507	                }
508	                if (tray->nozzle_temp > 0) {
509	                    tray_json["nozzle_temp_max"] = std::to_string(tray->nozzle_temp);
510	                }
511	            } else {
512	                tray_json["tray_info_idx"] = "";
513	                tray_json["tray_type"] = "";
514	                tray_json["tray_color"] = "00000000";
515	                tray_json["tray_slot_placeholder"] = "1";
516	            }
517	
518	            tray_array.push_back(tray_json);
519	        }
520	        ams_unit["tray"] = tray_array;
521	        ams_array.push_back(ams_unit);
522	    }
523	
524	    // Format as hex strings (matching BBL protocol)
525	    std::ostringstream ams_exist_ss;
526	    ams_exist_ss << std::hex << std::uppercase << ams_exist_bits;
527	    std::ostringstream tray_exist_ss;
528	    tray_exist_ss << std::hex << std::uppercase << tray_exist_bits;
529	
530	    ams_json["ams"] = ams_array;
531	    ams_json["ams_exist_bits"] = ams_exist_ss.str();
532	    ams_json["tray_exist_bits"] = tray_exist_ss.str();
533	
534	    // Wrap in the expected structure for ParseV1_0
535	    nlohmann::json print_json = nlohmann::json::object();
536	    print_json["ams"] = ams_json;
537	
538	    // Call the parser to populate DevFilaSystem
539	    DevFilaSystemParser::ParseV1_0(print_json, obj, obj->GetFilaSystem(), false);
540	    BOOST_LOG_TRIVIAL(info) << "MoonrakerPrinterAgent::build_ams_payload: Parsed " << trays.size() << " trays";
541	
542	    // Set printer_type so update_sync_status() can match it against the preset's printer type.
543	    // Without this, the comparison fails and all sync badges are cleared.
544	    obj->printer_type = device_info.model_id;
545	
546	    // Set push counters so is_info_ready() returns true for pull-mode agents.
547	    if (obj->m_push_count == 0) {
548	        obj->m_push_count = 1;
549	    }
550	    if (obj->m_full_msg_count == 0) {
551	        obj->m_full_msg_count = 1;
552	    }
553	    obj->last_push_time = std::chrono::system_clock::now();
554	
555	    // Set storage state - Moonraker printers use virtual_sdcard, storage is always available.
556	    // This is required for SelectMachineDialog to allow printing (otherwise it blocks with "No SD card").
557	    obj->GetStorage()->set_sdcard_state(DevStorage::HAS_SDCARD_NORMAL);
558	
559	    // Populate module_vers so is_info_ready() passes the version check.
560	    // Moonraker printers don't have BBL-style version info, but we need a non-empty map.
561	    if (obj->module_vers.empty()) {
562	        DevFirmwareVersionInfo ota_info;
563	        ota_info.name = "ota";
564	        ota_info.sw_ver = "1.0.0";  // Placeholder version for Moonraker printers
565	        obj->module_vers.emplace("ota", ota_info);
566	    }
567	}
