569	bool MoonrakerPrinterAgent::fetch_filament_info(std::string dev_id)
570	{
571	    std::vector<AmsTrayData> trays;
572	    int max_lane_index = 0;
573	
574	    // Try Moonraker filament data (more generic, supports any filament changer
575	    // software that reports lane data to Moonraker like AFC and recent Happy
576	    // Hare as of Feb 15, 2026)
577	    if (fetch_moonraker_filament_data(trays, max_lane_index)) {
578	        BOOST_LOG_TRIVIAL(info) << "MoonrakerPrinterAgent::fetch_filament_info: Detected Moonraker filament system with "
579	                                << (max_lane_index + 1) << " lanes";
580	        int ams_count = (max_lane_index + 4) / 4;
581	        build_ams_payload(ams_count, max_lane_index, trays);
582	        return true;
583	    }
584	
585	    // Attempt Happy Hare first (more widely adopted, supports more filament changers)
586	    if (fetch_hh_filament_info(trays, max_lane_index)) {
587	        BOOST_LOG_TRIVIAL(info) << "MoonrakerPrinterAgent::fetch_filament_info: Detected Happy Hare MMU with "
588	                                << (max_lane_index + 1) << " gates";
589	        int ams_count = (max_lane_index + 4) / 4;
590	        build_ams_payload(ams_count, max_lane_index, trays);
591	        return true;
592	    }
593	
594	    // No MMU detected - this is normal for printers without MMU, not an error
595	    BOOST_LOG_TRIVIAL(info) << "MoonrakerPrinterAgent::fetch_filament_info: No MMU system detected (neither HH nor Moonraker)";
596	    return false;
597	}
