599	std::string MoonrakerPrinterAgent::trim_and_upper(const std::string& input)
600	{
601	    std::string result = input;
602	    boost::trim(result);
603	    std::transform(result.begin(), result.end(), result.begin(),
604	                   [](unsigned char c) { return static_cast<char>(std::toupper(c)); });
605	    return result;
606	}
