608	std::string MoonrakerPrinterAgent::map_filament_type_to_generic_id(const std::string& filament_type)
609	{
610	    const std::string upper = trim_and_upper(filament_type);
611	
612	    // Map to OrcaFilamentLibrary preset IDs (compatible with all printers)
613	    // Source: resources/profiles/OrcaFilamentLibrary/filament/
614	
615	    // PLA variants
616	    if (upper == "PLA")           return "OGFL99";
617	    if (upper == "PLA-CF")        return "OGFL98";
618	    if (upper == "PLA SILK" || upper == "PLA-SILK") return "OGFL96";
619	    if (upper == "PLA HIGH SPEED" || upper == "PLA-HS" || upper == "PLA HS") return "OGFL95";
620	
621	    // ABS/ASA variants
622	    if (upper == "ABS")           return "OGFB99";
623	    if (upper == "ASA")           return "OGFB98";
624	
625	    // PETG/PET variants
626	    if (upper == "PETG" || upper == "PET") return "OGFG99";
627	    if (upper == "PCTG")          return "OGFG97";
628	
629	    // PA/Nylon variants
630	    if (upper == "PA" || upper == "NYLON") return "OGFN99";
631	    if (upper == "PA-CF")         return "OGFN98";
632	    if (upper == "PPA" || upper == "PPA-CF") return "OGFN97";
633	    if (upper == "PPA-GF")        return "OGFN96";
634	
635	    // PC variants
636	    if (upper == "PC")            return "OGFC99";
637	
638	    // PP/PE variants
639	    if (upper == "PE")            return "OGFP99";
640	    if (upper == "PP")            return "OGFP97";
641	
642	    // Support materials
643	    if (upper == "PVA")           return "OGFS99";
644	    if (upper == "HIPS")          return "OGFS98";
645	    if (upper == "BVOH")          return "OGFS97";
646	
647	    // TPU variants
648	    if (upper == "TPU")           return "OGFU99";
649	
650	    // Other materials
651	    if (upper == "EVA")           return "OGFR99";
652	    if (upper == "PHA")           return "OGFR98";
653	    if (upper == "COPE")          return "OGFLC99";
654	    if (upper == "SBS")           return "OFLSBS99";
655	
656	    // Unknown material
657	    return UNKNOWN_FILAMENT_ID;
658	}
