691	std::string MoonrakerPrinterAgent::normalize_color_value(const std::string& color)
692	{
693	    std::string value = color;
694	    boost::trim(value);
695	
696	    // Remove 0x or 0X prefix if present
697	    if (value.size() >= 2 && (value.rfind("0x", 0) == 0 || value.rfind("0X", 0) == 0)) {
698	        value = value.substr(2);
699	    }
700	    // Remove # prefix if present
701	    if (!value.empty() && value[0] == '#') {
702	        value = value.substr(1);
703	    }
704	
705	    // Extract only hex digits
706	    std::string normalized;
707	    for (char c : value) {
708	        if (std::isxdigit(static_cast<unsigned char>(c))) {
709	            normalized.push_back(static_cast<char>(std::toupper(static_cast<unsigned char>(c))));
710	        }
711	    }
712	
713	    // If 6 hex digits, add FF alpha
714	    if (normalized.size() == 6) {
715	        normalized += "FF";
716	    }
717	
718	    // Validate length - return default if invalid
719	    if (normalized.size() != 8) {
720	        return "00000000";
721	    }
722	
723	    return normalized;
724	}
