726	// Fetch filament info from moonraker database
727	bool MoonrakerPrinterAgent::fetch_moonraker_filament_data(std::vector<AmsTrayData>& trays, int& max_lane_index)
728	{
729	    // Fetch lane data from Moonraker database
730	    std::string url = join_url(device_info.base_url, "/server/database/item?namespace=lane_data");
731	
732	    std::string response_body;
733	    bool success = false;
734	    std::string http_error;
735	
736	    auto http = Http::get(url);
737	    if (!device_info.api_key.empty()) {
738	        http.header("X-Api-Key", device_info.api_key);
739	    }
740	    http.timeout_connect(5)
741	        .timeout_max(10)
742	        .on_complete([&](std::string body, unsigned status) {
743	            if (status == 200) {
744	                response_body = body;
745	                success = true;
746	            } else {
747	                http_error = "HTTP error: " + std::to_string(status);
748	            }
749	        })
750	        .on_error([&](std::string body, std::string err, unsigned status) {
751	            http_error = err;
752	            if (status > 0) {
753	                http_error += " (HTTP " + std::to_string(status) + ")";
754	            }
755	        })
756	        .perform_sync();
757	
758	    if (!success) {
759	        BOOST_LOG_TRIVIAL(warning) << "MoonrakerPrinterAgent::fetch_moonraker_filament_data: Failed to fetch lane data: " << http_error;
760	        return false;

760	        return false;
761	    }
762	
763	    auto json = nlohmann::json::parse(response_body, nullptr, false, true);
764	    if (json.is_discarded()) {
765	        BOOST_LOG_TRIVIAL(warning) << "MoonrakerPrinterAgent::fetch_moonraker_filament_data: Invalid JSON response";
766	        return false;
767	    }
768	
769	    // Expected structure: { "result": { "namespace": "lane_data", "value": { "lane1": {...}, ... } } }
770	    if (!json.contains("result") || !json["result"].contains("value") || !json["result"]["value"].is_object()) {
771	        BOOST_LOG_TRIVIAL(warning) << "MoonrakerPrinterAgent::fetch_moonraker_filament_data: Unexpected JSON structure or no lane_data found";
772	        return false;
773	    }
774	
775	    // Parse response into AmsTrayData
776	    const auto& value = json["result"]["value"];
777	    trays.clear();
778	    max_lane_index = 0;
779	
780	    for (const auto& [lane_key, lane_obj] : value.items()) {
781	        if (!lane_obj.is_object()) {
782	            continue;
783	        }
784	
785	        // Extract lane index from the "lane" field (tool number, 0-based)
786	        std::string lane_str = safe_json_string(lane_obj, "lane");
787	        int lane_index = -1;
788	        if (!lane_str.empty()) {
789	            try {
790	                lane_index = std::stoi(lane_str);
791	            } catch (...) {
792	                lane_index = -1;
793	            }
794	        }
795	
796	        if (lane_index < 0) {
797	            continue;
798	        }
799	
800	        AmsTrayData tray;
801	        tray.slot_index = lane_index;
802	        tray.tray_color = safe_json_string(lane_obj, "color");
803	        tray.tray_type = safe_json_string(lane_obj, "material");
804	        tray.bed_temp = safe_json_int(lane_obj, "bed_temp");
805	        tray.nozzle_temp = safe_json_int(lane_obj, "nozzle_temp");
806	        tray.has_filament = !tray.tray_type.empty();
807	        auto* bundle = GUI::wxGetApp().preset_bundle;
808	        tray.tray_info_idx = bundle
809	            ? bundle->filaments.filament_id_by_type(tray.tray_type)
810	            : map_filament_type_to_generic_id(tray.tray_type);
811	
812	        max_lane_index = std::max(max_lane_index, lane_index);
813	        trays.push_back(tray);
814	    }
815	
816	    if (trays.empty()) {
817	        BOOST_LOG_TRIVIAL(info) << "MoonrakerPrinterAgent::fetch_moonraker_filament_data: No lanes found";
818	        return false;
819	    }
820	
821	    return true;
822	}
