824	// Fetch filament info from Happy Hare MMU
825	bool MoonrakerPrinterAgent::fetch_hh_filament_info(std::vector<AmsTrayData>& trays, int& max_lane_index)
826	{
827	    // Query Happy Hare MMU status
828	    std::string url = join_url(device_info.base_url, "/printer/objects/query?mmu");
829	
830	    std::string response_body;
831	    bool success = false;
832	    std::string http_error;
833	
834	    auto http = Http::get(url);
835	    if (!device_info.api_key.empty()) {
836	        http.header("X-Api-Key", device_info.api_key);
837	    }
838	    http.timeout_connect(5)
839	        .timeout_max(10)
840	        .on_complete([&](std::string body, unsigned status) {
841	            if (status == 200) {
842	                response_body = body;
843	                success = true;
844	            } else {
845	                http_error = "HTTP error: " + std::to_string(status);
846	            }
847	        })
848	        .on_error([&](std::string body, std::string err, unsigned status) {
849	            http_error = err;
850	            if (status > 0) {
851	                http_error += " (HTTP " + std::to_string(status) + ")";
852	            }
853	        })
854	        .perform_sync();
855	
856	    if (!success) {
857	        BOOST_LOG_TRIVIAL(debug) << "MoonrakerPrinterAgent::fetch_hh_filament_info: Failed to fetch HH data: " << http_error;
858	        return false;
859	    }
860	
861	    auto json = nlohmann::json::parse(response_body, nullptr, false, true);
862	    if (json.is_discarded()) {
863	        BOOST_LOG_TRIVIAL(debug) << "MoonrakerPrinterAgent::fetch_hh_filament_info: Invalid JSON response";
864	        return false;
865	    }
866	
867	    // Expected structure: { "result": { "status": { "mmu": { ... } } } }
868	    if (!json.contains("result") || !json["result"].contains("status") ||
869	        !json["result"]["status"].contains("mmu") || !json["result"]["status"]["mmu"].is_object()) {
870	        BOOST_LOG_TRIVIAL(debug) << "MoonrakerPrinterAgent::fetch_hh_filament_info: No mmu object in response";
871	        return false;
872	    }
873	
874	    const auto& mmu = json["result"]["status"]["mmu"];
875	
876	    // Check if HH is installed (empty mmu object means HH not installed)
877	    if (mmu.empty()) {
878	        BOOST_LOG_TRIVIAL(debug) << "MoonrakerPrinterAgent::fetch_hh_filament_info: Empty mmu object (HH not installed)";
879	        return false;
880	    }
881	
882	    // Get num_gates
883	    if (!mmu.contains("num_gates") || !mmu["num_gates"].is_number()) {
884	        BOOST_LOG_TRIVIAL(debug) << "MoonrakerPrinterAgent::fetch_hh_filament_info: No num_gates field";
885	        return false;
886	    }
887	
888	    int num_gates = mmu["num_gates"].get<int>();
889	    if (num_gates <= 0) {
890	        BOOST_LOG_TRIVIAL(warning) << "MoonrakerPrinterAgent::fetch_hh_filament_info: Invalid num_gates: " << num_gates;
891	        return false;
892	    }
893	
894	    // Get arrays
895	    const auto& gate_status = mmu.contains("gate_status") ? mmu["gate_status"] : nlohmann::json::array();
896	    const auto& gate_material = mmu.contains("gate_material") ? mmu["gate_material"] : nlohmann::json::array();
897	    const auto& gate_color = mmu.contains("gate_color") ? mmu["gate_color"] : nlohmann::json::array();
898	    const auto& gate_temperature = mmu.contains("gate_temperature") ? mmu["gate_temperature"] : nlohmann::json::array();
899	
900	    if (!gate_status.is_array() || !gate_material.is_array() ||
901	        !gate_color.is_array() || !gate_temperature.is_array()) {
902	        BOOST_LOG_TRIVIAL(warning) << "MoonrakerPrinterAgent::fetch_hh_filament_info: HH arrays not found or invalid type";
903	        return false;
904	    }
905	
906	    // Parse gate data
907	    trays.clear();
908	    max_lane_index = 0;
909	
910	    for (int gate_idx = 0; gate_idx < num_gates; ++gate_idx) {
911	        // Check gate_status: -1 = unknown, 0 = empty, 1 or 2 = available
912	        int status = safe_array_int(gate_status, gate_idx);
913	        if (status <= 0) {
914	            continue;  // Skip unknown or empty gates
915	        }
916	
917	        // Extract gate data
918	        std::string material = safe_array_string(gate_material, gate_idx);
919	        std::string color = safe_array_string(gate_color, gate_idx);
920	        int nozzle_temp = safe_array_int(gate_temperature, gate_idx);
921	
922	        // Skip if no material type (empty gate)
923	        if (material.empty()) {
924	            continue;
925	        }
926	
927	        AmsTrayData tray;
928	        tray.slot_index = gate_idx;
929	        tray.tray_type = material;
930	        tray.tray_color = color;
931	        tray.nozzle_temp = nozzle_temp;
932	        tray.bed_temp = 0;  // HH doesn't provide bed temp in gate arrays
933	        tray.has_filament = true;
934	
935	        auto* bundle = GUI::wxGetApp().preset_bundle;
936	        tray.tray_info_idx = bundle
937	            ? bundle->filaments.filament_id_by_type(tray.tray_type)
938	            : map_filament_type_to_generic_id(tray.tray_type);
939	
940	        max_lane_index = std::max(max_lane_index, gate_idx);
941	        trays.push_back(tray);
942	    }
943	
944	    if (trays.empty()) {
945	        BOOST_LOG_TRIVIAL(info) << "MoonrakerPrinterAgent::fetch_hh_filament_info: No valid HH gates found";
946	        return false;
947	    }
948	
949	    return true;
950	}
