952	int MoonrakerPrinterAgent::handle_request(const std::string& dev_id, const std::string& json_str)
953	{
954	    auto json = nlohmann::json::parse(json_str, nullptr, false);
955	    if (json.is_discarded()) {
956	        BOOST_LOG_TRIVIAL(error) << "MoonrakerPrinterAgent: Invalid JSON request";
957	        return BAMBU_NETWORK_ERR_INVALID_RESULT;
958	    }
959	
960	    // Handle info commands
961	    if (json.contains("info") && json["info"].contains("command")) {
962	        const auto& command = json["info"]["command"];
963	        if (command.is_string() && command.get<std::string>() == "get_version") {
964	            return send_version_info(dev_id);
965	        }
966	    }
967	
968	    // Handle system commands
969	    if (json.contains("system") && json["system"].contains("command")) {
970	        const auto& command = json["system"]["command"];
971	        if (command.is_string() && command.get<std::string>() == "get_access_code") {
972	            return send_access_code(dev_id);
973	        }
974	    }
975	
976	    // Handle print commands
977	    if (json.contains("print") && json["print"].contains("command")) {
978	        const auto& command = json["print"]["command"];
979	        if (!command.is_string()) {
980	            BOOST_LOG_TRIVIAL(warning) << "MoonrakerPrinterAgent: print command is not a string";
981	            return BAMBU_NETWORK_ERR_INVALID_RESULT;
982	        }
983	
984	        const std::string cmd = command.get<std::string>();
985	
986	        // Handle gcode_line command - this is how G-code commands are sent from OrcaSlicer
987	        if (cmd == "gcode_line") {
988	            if (!json["print"].contains("param") || !json["print"]["param"].is_string()) {
989	                BOOST_LOG_TRIVIAL(error) << "MoonrakerPrinterAgent: gcode_line missing param value, full json: " << json_str;
990	                return BAMBU_NETWORK_ERR_INVALID_RESULT;
991	            }
992	            std::string gcode = json["print"]["param"].get<std::string>();
993	
994	            // Extract sequence_id from request if present
995	            std::string sequence_id;
996	            if (json["print"].contains("sequence_id") && json["print"]["sequence_id"].is_string()) {
997	                sequence_id = json["print"]["sequence_id"].get<std::string>();
998	            }
999	
1000	            nlohmann::json response;
1001	            response["print"]["command"] = "gcode_line";
1002	            if (!sequence_id.empty()) {
1003	                response["print"]["sequence_id"] = sequence_id;
1004	            }
1005	            response["print"]["param"] = gcode;
1006	
1007	            if (send_gcode(dev_id, gcode)) {
1008	                response["print"]["result"] = "success";
1009	                dispatch_message(dev_id, response.dump());
1010	                return BAMBU_NETWORK_SUCCESS;
1011	            }
1012	            response["print"]["result"] = "failed";
1013	            dispatch_message(dev_id, response.dump());
1014	            return BAMBU_NETWORK_ERR_CONNECTION_TO_PRINTER_FAILED;
1015	        }
1016	
1017	        // Print control commands
1018	        if (cmd == "pause") {
1019	            return pause_print(dev_id);
1020	        }
1021	        if (cmd == "resume") {
1022	            return resume_print(dev_id);
1023	        }
1024	        if (cmd == "stop") {
1025	            return cancel_print(dev_id);
1026	        }
1027	
1028	        // Bed temperature - UI sends "temp" field
1029	        if (cmd == "set_bed_temp") {
1030	            if (json["print"].contains("temp") && json["print"]["temp"].is_number()) {
1031	                int         temp  = json["print"]["temp"].get<int>();
1032	                std::string gcode = "SET_HEATER_TEMPERATURE HEATER=heater_bed TARGET=" + std::to_string(temp);
1033	                send_gcode(dev_id, gcode);
1034	                return BAMBU_NETWORK_SUCCESS;
1035	            }
1036	        }
1037	
1038	        // Nozzle temperature - UI sends "target_temp" and "extruder_index" fields
1039	        if (cmd == "set_nozzle_temp") {
1040	            if (json["print"].contains("target_temp") && json["print"]["target_temp"].is_number()) {
1041	                int temp         = json["print"]["target_temp"].get<int>();
1042	                int extruder_idx = 0; // Default to main extruder
1043	                if (json["print"].contains("extruder_index") && json["print"]["extruder_index"].is_number()) {
1044	                    extruder_idx = json["print"]["extruder_index"].get<int>();
1045	                }
1046	                std::string heater = (extruder_idx == 0) ? "extruder" : "extruder" + std::to_string(extruder_idx);
1047	                std::string gcode  = "SET_HEATER_TEMPERATURE HEATER=" + heater + " TARGET=" + std::to_string(temp);
1048	                send_gcode(dev_id, gcode);
1049	                return BAMBU_NETWORK_SUCCESS;
1050	            }
1051	        }
1052	
1053	        if (cmd == "home") {
1054	            return send_gcode(dev_id, "G28") ? BAMBU_NETWORK_SUCCESS : BAMBU_NETWORK_ERR_SEND_MSG_FAILED;
1055	        }
1056	    }
1057	
1058	    return BAMBU_NETWORK_SUCCESS;
1059	}
