1084	bool MoonrakerPrinterAgent::fetch_device_info(const std::string&   base_url,
1085	                                              const std::string&   api_key,
1086	                                              MoonrakerDeviceInfo& info,
1087	                                              std::string&         error) const
1088	{
1089	    auto fetch_json = [&](const std::string& url, nlohmann::json& out) {
1090	        std::string response_body;
1091	        bool        success = false;
1092	        std::string http_error;
1093	
1094	        auto http = Http::get(url);
1095	        if (!api_key.empty()) {
1096	            http.header("X-Api-Key", api_key);
1097	        }
1098	        http.timeout_connect(5)
1099	            .timeout_max(10)
1100	            .on_complete([&](std::string body, unsigned status) {
1101	                if (status == 200) {
1102	                    response_body = body;
1103	                    success       = true;
1104	                } else {
1105	                    http_error = "HTTP error: " + std::to_string(status);
1106	                }
1107	            })
1108	            .on_error([&](std::string body, std::string err, unsigned status) {
1109	                http_error = err;
1110	                if (status > 0) {
1111	                    http_error += " (HTTP " + std::to_string(status) + ")";
1112	                }
1113	            })
1114	            .perform_sync();
1115	
1116	        if (!success) {
1117	            error = http_error.empty() ? "Connection failed" : http_error;
1118	            return false;
1119	        }
1120	
1121	        out = nlohmann::json::parse(response_body, nullptr, false, true);
1122	        if (out.is_discarded()) {
1123	            error = "Invalid JSON response";
1124	            return false;
1125	        }
1126	        return true;
1127	    };
1128	
1129	    nlohmann::json json;
1130	    std::string    url = join_url(base_url, "/server/info");
1131	    if (!fetch_json(url, json)) {
1132	        return false;
1133	    }
1134	
1135	    nlohmann::json result = json.contains("result") ? json["result"] : json;
1136	    info.dev_name         = result.value("machine_name", result.value("hostname", ""));
1137	    info.version          = result.value("moonraker_version", "");
1138	    info.klippy_state     = result.value("klippy_state", "");
1139	
1140	    return true;
1141	}
