1322	void MoonrakerPrinterAgent::announce_printhost_device()
1323	{
1324	    OnMsgArrivedFn ssdp_fn;
1325	    {
1326	        std::lock_guard<std::recursive_mutex> lock(state_mutex);
1327	        ssdp_fn = on_ssdp_msg_fn;
1328	        if (!ssdp_fn) {
1329	            return;
1330	        }
1331	        if (ssdp_announced_host == device_info.base_url && !ssdp_announced_id.empty()) {
1332	            return;
1333	        }
1334	    }
1335	
1336	    // Try to fetch actual device name from Moonraker
1337	    // Priority: 1) Moonraker hostname, 2) Preset model name, 3) Generic fallback
1338	    std::string         dev_name;
1339	    MoonrakerDeviceInfo info;
1340	    std::string         fetch_error;
1341	    if (fetch_device_info(device_info.base_url, device_info.api_key, info, fetch_error) && !info.dev_name.empty()) {
1342	        dev_name = info.dev_name;
1343	    } else {
1344	        dev_name = device_info.model_name.empty() ? "Moonraker Printer" : device_info.model_name;
1345	    }
1346	
1347	    const std::string model_id = device_info.model_id;
1348	
1349	    if (auto* app_config = GUI::wxGetApp().app_config) {
1350	        const std::string access_code = device_info.api_key.empty() ? "88888888" : device_info.api_key;
1351	        app_config->set_str("access_code", device_info.dev_id, access_code);
1352	        app_config->set_str("user_access_code", device_info.dev_id, access_code);
1353	    }
1354	
1355	    nlohmann::json payload;
1356	    payload["dev_name"]     = dev_name;
1357	    payload["dev_id"]       = device_info.dev_id;
1358	    payload["dev_ip"]       = device_info.dev_ip;
1359	    payload["dev_type"]     = model_id.empty() ? dev_name : model_id;
1360	    payload["dev_signal"]   = "0";
1361	    payload["connect_type"] = "lan";
1362	    payload["bind_state"]   = "free";
1363	    payload["sec_link"]     = "secure";
1364	    payload["ssdp_version"] = "v1";
1365	
1366	    ssdp_fn(payload.dump());
1367	
1368	    {
1369	        std::lock_guard<std::recursive_mutex> lock(state_mutex);
1370	        ssdp_announced_host = device_info.base_url;
1371	        ssdp_announced_id   = device_info.dev_id;
1372	
1373	        // Set this as the selected machine if nothing is currently selected
1374	        if (selected_machine.empty()) {
1375	            selected_machine = device_info.dev_id;
1376	        }
1377	    }
1378	}
