1380	void MoonrakerPrinterAgent::dispatch_local_connect(int state, const std::string& dev_id, const std::string& msg)
1381	{
1382	    OnLocalConnectedFn local_fn;
1383	    QueueOnMainFn      queue_fn;
1384	    {
1385	        std::lock_guard<std::recursive_mutex> lock(state_mutex);
1386	        local_fn = on_local_connect_fn;
1387	        queue_fn = queue_on_main_fn;
1388	    }
1389	    if (!local_fn) {
1390	        return;
1391	    }
1392	
1393	    auto dispatch = [state, dev_id, msg, local_fn]() { local_fn(state, dev_id, msg); };
1394	    if (queue_fn) {
1395	        queue_fn(dispatch);
1396	    } else {
1397	        dispatch();
1398	    }
1399	}
