1441	void MoonrakerPrinterAgent::run_status_stream(std::string dev_id, std::string base_url, std::string api_key)
1442	{
1443	    WsEndpoint endpoint;
1444	    if (!parse_ws_endpoint(base_url, endpoint)) {
1445	        BOOST_LOG_TRIVIAL(warning) << "MoonrakerPrinterAgent: websocket endpoint invalid for base_url=" << base_url;
1446	        return;
1447	    }
1448	    if (endpoint.secure) {
1449	        BOOST_LOG_TRIVIAL(warning) << "MoonrakerPrinterAgent: websocket wss not supported for base_url=" << base_url;
1450	        return;
1451	    }
1452	
1453	    // Reconnection logic
1454	    ws_reconnect_requested.store(false); // Reset reconnect flag
1455	    int       retry_count   = 0;
1456	    const int max_retries   = 10;
1457	    const int base_delay_ms = 1000;
1458	
1459	    while (!ws_stop.load() && retry_count < max_retries) {
1460	        bool connection_lost = false; // Flag to distinguish clean shutdown from unexpected disconnect
1461	
1462	        try {
1463	            net::io_context   ioc;
1464	            tcp::resolver     resolver{ioc};
1465	            beast::tcp_stream stream{ioc};
1466	
1467	            stream.expires_after(std::chrono::seconds(10));
1468	            auto const results = resolver.resolve(endpoint.host, endpoint.port);
1469	            stream.connect(results);
1470	
1471	            websocket::stream<beast::tcp_stream> ws{std::move(stream)};
1472	            ws.set_option(websocket::stream_base::decorator([&](websocket::request_type& req) {
1473	                req.set(http::field::user_agent, "OrcaSlicer");
1474	                if (!api_key.empty()) {
1475	                    req.set("X-Api-Key", api_key);
1476	                }
1477	            }));
1478	
1479	            std::string host_header = endpoint.host;
1480	            if (!endpoint.port.empty() && endpoint.port != "80") {
1481	                host_header += ":" + endpoint.port;
1482	            }
1483	            ws.handshake(host_header, endpoint.target);
1484	            ws.text(true);
1485	
1486	            // Send client identification
1487	            nlohmann::json identify;
1488	            identify["jsonrpc"]               = "2.0";
1489	            identify["method"]                = "server.connection.identify";
1490	            identify["params"]["client_name"] = "OrcaSlicer";
1491	            identify["params"]["version"]     = MoonrakerPrinterAgent_VERSION;
1492	            identify["params"]["type"]        = "agent";
1493	            identify["params"]["url"]         = "https://github.com/SoftFever/OrcaSlicer";
1494	            identify["id"]                    = 0;
1495	            ws.write(net::buffer(identify.dump()));
1496	
1497	            std::set<std::string> subscribe_objects = {"print_stats", "virtual_sdcard"};
1498	            std::set<std::string> available_objects;
1499	            std::string           list_error;
1500	            if (fetch_object_list(base_url, api_key, available_objects, list_error)) {
1501	                {
1502	                    std::lock_guard<std::recursive_mutex> lock(payload_mutex);
1503	                    this->available_objects = std::move(available_objects);
1504	                }
1505	
1506	                if (this->available_objects.count("heater_bed") != 0) {
1507	                    subscribe_objects.insert("heater_bed");
1508	                }
1509	                if (this->available_objects.count("fan") != 0) {
1510	                    subscribe_objects.insert("fan");
1511	                }
1512	
1513	                // Add toolhead for homing status
1514	                if (this->available_objects.count("toolhead") != 0) {
1515	                    subscribe_objects.insert("toolhead");
1516	                }
1517	
1518	                // Add display_status for layer info (if available)
1519	                if (this->available_objects.count("display_status") != 0) {
1520	                    subscribe_objects.insert("display_status");
1521	                }
1522	
1523	                for (const auto& name : this->available_objects) {
1524	                    if (name == "extruder" || name.rfind("extruder", 0) == 0) {
1525	                        subscribe_objects.insert(name);
1526	                        if (name == "extruder") {
1527	                            break;
1528	                        }
1529	                    }
1530	                }
1531	            } else {
1532	                subscribe_objects.insert("extruder");
1533	                subscribe_objects.insert("heater_bed");
1534	                subscribe_objects.insert("toolhead"); // Add toolhead as fallback
1535	                subscribe_objects.insert("fan");      // Try to subscribe to fan as fallback
1536	            }
1537	
1538	            nlohmann::json subscribe;
1539	            subscribe["jsonrpc"]   = "2.0";
1540	            subscribe["method"]    = "printer.objects.subscribe";
1541	            nlohmann::json objects = nlohmann::json::object();
1542	            for (const auto& name : subscribe_objects) {
1543	                objects[name] = nullptr;
1544	            }
1545	            subscribe["params"]["objects"] = std::move(objects);
1546	            subscribe["id"]                = 1;
1547	            ws.write(net::buffer(subscribe.dump()));
1548	
1549	            // Read loop
1550	            while (!ws_stop.load()) {
1551	                ws.next_layer().expires_after(std::chrono::seconds(2));
1552	                beast::flat_buffer buffer;
1553	                beast::error_code  ec;
1554	                ws.read(buffer, ec);
1555	                if (ec == beast::error::timeout) {
1556	                    const auto now_ms = static_cast<uint64_t>(
1557	                        std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now().time_since_epoch()).count());
1558	                    const auto last_ms = ws_last_emit_ms.load();
1559	                    if (last_ms == 0 || now_ms - last_ms >= 10000) {
1560	                        nlohmann::json message;
1561	                        {
1562	                            std::lock_guard<std::recursive_mutex> lock(payload_mutex);
1563	                            message = build_print_payload_locked();
1564	                        }
1565	                        dispatch_message(dev_id, message.dump());
1566	                        ws_last_emit_ms.store(now_ms);
1567	                    }
1568	                    continue;
1569	                }
1570	                if (ec == websocket::error::closed) {
1571	                    connection_lost = true;
1572	                    break;
1573	                }
1574	                if (ec) {
1575	                    BOOST_LOG_TRIVIAL(warning) << "MoonrakerPrinterAgent: websocket read error: " << ec.message();
1576	                    connection_lost = true;
1577	                    break;
1578	                }
1579	                handle_ws_message(dev_id, beast::buffers_to_string(buffer.data()));
1580	                // Check if handle_ws_message triggered reconnection request
1581	                if (ws_reconnect_requested.exchange(false)) {
1582	                    connection_lost = true;
1583	                    break;
1584	                }
1585	            }
1586	
1587	            beast::error_code ec;
1588	            ws.close(websocket::close_code::normal, ec);
1589	
1590	            // Only reset retry count on clean shutdown (not connection_lost)
1591	            if (!connection_lost && !ws_stop.load()) {
1592	                retry_count = 0;
1593	            }
1594	
1595	        } catch (const std::exception& e) {
1596	            BOOST_LOG_TRIVIAL(warning) << "MoonrakerPrinterAgent: websocket disconnected: " << e.what();
1597	            connection_lost = true;
1598	        }
1599	
1600	        // Exit loop on clean shutdown
1601	        if (!connection_lost) {
1602	            break;
1603	        }
1604	
1605	        // Check if we should stop reconnection attempts
1606	        if (ws_stop.load()) {
1607	            break;
1608	        }
1609	
1610	        // Exponential backoff before reconnection
1611	        int delay_ms = base_delay_ms * (1 << std::min(retry_count, 5));
1612	        BOOST_LOG_TRIVIAL(info) << "MoonrakerPrinterAgent: Reconnecting in " << delay_ms << "ms (attempt " << (retry_count + 1) << ")";
1613	        std::this_thread::sleep_for(std::chrono::milliseconds(delay_ms));
1614	        retry_count++;
1615	    }
1616	
1617	    if (retry_count >= max_retries) {
1618	        BOOST_LOG_TRIVIAL(error) << "MoonrakerPrinterAgent: Max reconnection attempts reached";
1619	        dispatch_local_connect(ConnectStatusLost, dev_id, "max_retries");
1620	    }
1621	}
