1623	void MoonrakerPrinterAgent::handle_ws_message(const std::string& dev_id, const std::string& payload)
1624	{
1625	    auto json = nlohmann::json::parse(payload, nullptr, false);
1626	    if (json.is_discarded()) {
1627	        BOOST_LOG_TRIVIAL(warning) << "MoonrakerPrinterAgent: Invalid WebSocket message JSON";
1628	        return;
1629	    }
1630	
1631	    bool updated     = false;
1632	    bool is_critical = false; // Track if this is a critical update that bypasses throttle
1633	
1634	    // Check for subscription response (has "result.status") - initial subscription is critical
1635	    if (json.contains("result") && json["result"].contains("status") && json["result"]["status"].is_object()) {
1636	        update_status_cache(json["result"]["status"]);
1637	        updated     = true;
1638	        is_critical = true; // Initial subscription response - dispatch immediately
1639	    }
1640	
1641	    // Check for status update notifications
1642	    if (json.contains("method") && json["method"].is_string()) {
1643	        const std::string method = json["method"].get<std::string>();
1644	        if (method == "notify_status_update" && json.contains("params") && json["params"].is_array() && !json["params"].empty() &&
1645	            json["params"][0].is_object()) {
1646	            update_status_cache(json["params"][0]);
1647	            updated = true;
1648	            // Note: is_critical stays false for regular status updates (telemetry)
1649	        } else if (method == "notify_klippy_ready") {
1650	            nlohmann::json updates;
1651	            updates["print_stats"]["state"] = "standby";
1652	            update_status_cache(updates);
1653	            updated     = true;
1654	            is_critical = true; // Klippy events are critical
1655	        } else if (method == "notify_klippy_shutdown") {
1656	            nlohmann::json updates;
1657	            updates["print_stats"]["state"] = "error";
1658	            update_status_cache(updates);
1659	            updated     = true;
1660	            is_critical = true; // Klippy events are critical
1661	        }
1662	        // Handle Klippy disconnect - update status and trigger reconnection
1663	        else if (method == "notify_klippy_disconnected") {
1664	            // Klippy disconnected - update status to reflect disconnect state
1665	            nlohmann::json updates;
1666	            updates["print_stats"]["state"] = "error";
1667	            update_status_cache(updates);
1668	            updated     = true;
1669	            is_critical = true; // Klippy events are critical
1670	            // Set flag to trigger reconnection after dispatching the status update
1671	            ws_reconnect_requested.store(true);
1672	            BOOST_LOG_TRIVIAL(warning) << "MoonrakerPrinterAgent: Klippy disconnected, triggering reconnection";
1673	        }
1674	    }
1675	
1676	    // Check for print state changes (critical - always dispatch immediately)
1677	    if (updated && !is_critical) {
1678	        std::string current_state;
1679	        {
1680	            std::lock_guard<std::recursive_mutex> lock(payload_mutex);
1681	            if (status_cache.contains("print_stats") && status_cache["print_stats"].contains("state") &&
1682	                status_cache["print_stats"]["state"].is_string()) {
1683	                current_state = status_cache["print_stats"]["state"].get<std::string>();
1684	            }
1685	        }
1686	
1687	        if (!current_state.empty() && current_state != last_print_state) {
1688	            is_critical      = true;
1689	            last_print_state = current_state;
1690	        }
1691	    }
1692	
1693	    if (updated) {
1694	        const auto now_ms = static_cast<uint64_t>(
1695	            std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now().time_since_epoch()).count());
1696	        const auto last_dispatch_ms = ws_last_dispatch_ms.load();
1697	
1698	        // Dispatch if: critical change OR throttle interval elapsed
1699	        const bool should_dispatch = is_critical || last_dispatch_ms == 0 || now_ms - last_dispatch_ms >= STATUS_UPDATE_INTERVAL_MS;
1700	
1701	        if (should_dispatch) {
1702	            nlohmann::json message;
1703	            {
1704	                std::lock_guard<std::recursive_mutex> lock(payload_mutex);
1705	                message = build_print_payload_locked();
1706	            }
1707	
1708	            dispatch_message(dev_id, message.dump());
1709	            ws_last_dispatch_ms.store(now_ms);
1710	            ws_last_emit_ms.store(now_ms); // Also update heartbeat timer
1711	        }
1712	        // else: skip dispatch, cache is updated for next dispatch cycle
1713	    }
1714	}
