1716	void MoonrakerPrinterAgent::update_status_cache(const nlohmann::json& updates)
1717	{
1718	    if (!updates.is_object()) {
1719	        return;
1720	    }
1721	
1722	    std::lock_guard<std::recursive_mutex> lock(payload_mutex);
1723	    if (!status_cache.is_object()) {
1724	        status_cache = nlohmann::json::object();
1725	    }
1726	
1727	    for (const auto& item : updates.items()) {
1728	        if (item.value().is_object()) {
1729	            nlohmann::json& target = status_cache[item.key()];
1730	            if (!target.is_object()) {
1731	                target = nlohmann::json::object();
1732	            }
1733	            for (const auto& field : item.value().items()) {
1734	                target[field.key()] = field.value();
1735	            }
1736	        } else {
1737	            status_cache[item.key()] = item.value();
1738	        }
1739	    }
1740	}
