1742	nlohmann::json MoonrakerPrinterAgent::build_print_payload_locked() const
1743	{
1744	    nlohmann::json payload;
1745	    payload["print"]["command"]            = "push_status";
1746	    payload["print"]["msg"]                = 0;
1747	    payload["print"]["support_mqtt_alive"] = true;
1748	
1749	    std::string state = "IDLE";
1750	    if (status_cache.contains("print_stats") && status_cache["print_stats"].contains("state") &&
1751	        status_cache["print_stats"]["state"].is_string()) {
1752	        state = map_moonraker_state(status_cache["print_stats"]["state"].get<std::string>());
1753	    }
1754	    payload["print"]["gcode_state"] = state;
1755	
1756	    // Map Moonraker state to Bambu stage numbers
1757	    int mc_print_stage = 0;
1758	    if (status_cache.contains("print_stats") && status_cache["print_stats"].contains("state")) {
1759	        std::string mr_state = status_cache["print_stats"]["state"].get<std::string>();
1760	        if (mr_state == "printing")
1761	            mc_print_stage = 1;
1762	        else if (mr_state == "paused")
1763	            mc_print_stage = 2;
1764	        else if (mr_state == "complete")
1765	            mc_print_stage = 3;
1766	        else if (mr_state == "error")
1767	            mc_print_stage = 4;
1768	    }
1769	    payload["print"]["mc_print_stage"] = mc_print_stage;
1770	
1771	    // Leave mc_print_error_code and print_error at 0
1772	    // UI expects numeric HMS codes - setting to 1 shows generic error dialog
1773	    // Only set if real mapping from Moonraker error strings to HMS codes is defined
1774	    payload["print"]["mc_print_error_code"] = 0;
1775	    payload["print"]["print_error"]         = 0;
1776	
1777	    // Map homed axes to bit field: X=bit0, Y=bit1, Z=bit2
1778	    // WARNING: This only sets bits 0-2, clearing support flags (bit 3+)
1779	    // Bit 3 = 220V voltage, bit 4 = auto recovery, etc.
1780	    // This is acceptable for Moonraker (no AMS, different feature set)
1781	    int home_flag = 0;
1782	    if (status_cache.contains("toolhead") && status_cache["toolhead"].contains("homed_axes")) {
1783	        std::string homed = status_cache["toolhead"]["homed_axes"].get<std::string>();
1784	        if (homed.find('X') != std::string::npos)
1785	            home_flag |= 1; // bit 0
1786	        if (homed.find('Y') != std::string::npos)
1787	            home_flag |= 2; // bit 1
1788	        if (homed.find('Z') != std::string::npos)
1789	            home_flag |= 4; // bit 2
1790	    }
1791	    payload["print"]["home_flag"] = home_flag;
1792	
1793	    // Moonraker doesn't provide temperature ranges via API - use hardcoded defaults
1794	    payload["print"]["nozzle_temp_range"] = {100, 370}; // Typical Klipper range
1795	    payload["print"]["bed_temp_range"]    = {0, 120};   // Typical bed range
1796	
1797	    payload["print"]["support_send_to_sd"] = true;
1798	    // Detect bed_leveling support from available objects (bed_mesh or probe)
1799	    // Default to 0 (not supported) if neither object exists
1800	    bool has_bed_leveling                    = (available_objects.count("bed_mesh") != 0 || available_objects.count("probe") != 0);
1801	    payload["print"]["support_bed_leveling"] = has_bed_leveling ? 1 : 0;
1802	
1803	    const nlohmann::json* extruder = nullptr;
1804	    if (status_cache.contains("extruder") && status_cache["extruder"].is_object()) {
1805	        extruder = &status_cache["extruder"];
1806	    } else {
1807	        for (const auto& item : status_cache.items()) {
1808	            if (item.value().is_object() && item.key().rfind("extruder", 0) == 0) {
1809	                extruder = &item.value();
1810	                break;
1811	            }
1812	        }
1813	    }
1814	
1815	    if (extruder) {
1816	        if (extruder->contains("temperature") && (*extruder)["temperature"].is_number()) {
1817	            payload["print"]["nozzle_temper"] = (*extruder)["temperature"].get<float>();
1818	        }
1819	        if (extruder->contains("target") && (*extruder)["target"].is_number()) {
1820	            payload["print"]["nozzle_target_temper"] = (*extruder)["target"].get<float>();
1821	        }
1822	    }
1823	
1824	    if (status_cache.contains("heater_bed") && status_cache["heater_bed"].is_object()) {
1825	        const auto& bed = status_cache["heater_bed"];
1826	        if (bed.contains("temperature") && bed["temperature"].is_number()) {
1827	            payload["print"]["bed_temper"] = bed["temperature"].get<float>();
1828	        }
1829	        if (bed.contains("target") && bed["target"].is_number()) {
1830	            payload["print"]["bed_target_temper"] = bed["target"].get<float>();
1831	        }
1832	    }
1833	
1834	    // Handle fan speed - only if Moonraker provides "fan" object (standard API)
1835	    if (status_cache.contains("fan") && status_cache["fan"].is_object() && !status_cache["fan"].empty()) {
1836	        const auto& fan = status_cache["fan"];
1837	        if (fan.contains("speed") && fan["speed"].is_number()) {
1838	            double speed = fan["speed"].get<double>();
1839	            int    pwm   = 0;
1840	            if (speed <= 1.0) {
1841	                pwm = static_cast<int>(speed * 255.0 + 0.5);
1842	            } else {
1843	                pwm = static_cast<int>(speed + 0.5);
1844	            }
1845	            pwm                          = std::clamp(pwm, 0, 255);
1846	            payload["print"]["fan_gear"] = pwm;
1847	        } else if (fan.contains("power") && fan["power"].is_number()) {
1848	            double power                 = fan["power"].get<double>();
1849	            int    pwm                   = static_cast<int>(power * 255.0 + 0.5);
1850	            pwm                          = std::clamp(pwm, 0, 255);
1851	            payload["print"]["fan_gear"] = pwm;
1852	        }
1853	    }
1854	    // If "fan" object doesn't exist, don't include fan_gear in payload
1855	
1856	    if (status_cache.contains("print_stats") && status_cache["print_stats"].contains("filename") &&
1857	        status_cache["print_stats"]["filename"].is_string()) {
1858	        payload["print"]["subtask_name"] = status_cache["print_stats"]["filename"].get<std::string>();
1859	    }
1860	
1861	    if (status_cache.contains("print_stats") && status_cache["print_stats"].contains("filename")) {
1862	        payload["print"]["gcode_file"] = status_cache["print_stats"]["filename"];
1863	    }
1864	
1865	    int mc_percent = -1;
1866	    if (status_cache.contains("virtual_sdcard") && status_cache["virtual_sdcard"].contains("progress") &&
1867	        status_cache["virtual_sdcard"]["progress"].is_number()) {
1868	        const double progress = status_cache["virtual_sdcard"]["progress"].get<double>();
1869	        if (progress >= 0.0) {
1870	            mc_percent = std::clamp(static_cast<int>(progress * 100.0 + 0.5), 0, 100);
1871	        }
1872	    }
1873	    if (mc_percent >= 0) {
1874	        payload["print"]["mc_percent"] = mc_percent;
1875	    }
1876	
1877	    if (status_cache.contains("print_stats") && status_cache["print_stats"].contains("total_duration") &&
1878	        status_cache["print_stats"].contains("print_duration") && status_cache["print_stats"]["total_duration"].is_number() &&
1879	        status_cache["print_stats"]["print_duration"].is_number()) {

1880	        const double total   = status_cache["print_stats"]["total_duration"].get<double>();
1881	        const double elapsed = status_cache["print_stats"]["print_duration"].get<double>();
1882	        if (total > 0.0 && elapsed >= 0.0) {
1883	            const auto remaining_minutes          = std::max(0, static_cast<int>((total - elapsed) / 60.0));
1884	            payload["print"]["mc_remaining_time"] = remaining_minutes;
1885	        }
1886	    }
1887	
1888	    const auto now_ms = static_cast<uint64_t>(
1889	        std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count());
1890	    payload["t_utc"] = now_ms;
1891	
1892	    return payload;
1893	}
