1895	void MoonrakerPrinterAgent::dispatch_message(const std::string& dev_id, const std::string& payload)
1896	{
1897	    OnMessageFn   local_fn;
1898	    OnMessageFn   cloud_fn;
1899	    QueueOnMainFn queue_fn;
1900	    {
1901	        std::lock_guard<std::recursive_mutex> lock(state_mutex);
1902	        local_fn = on_local_message_fn;
1903	        cloud_fn = on_message_fn;
1904	        queue_fn = queue_on_main_fn;
1905	    }
1906	
1907	    if (!local_fn && !cloud_fn) {
1908	        BOOST_LOG_TRIVIAL(warning) << "MoonrakerPrinterAgent: dispatch_message - no message callback registered!";
1909	        return;
1910	    }
1911	
1912	    auto dispatch = [dev_id, payload, local_fn, cloud_fn]() {
1913	        if (local_fn) {
1914	            local_fn(dev_id, payload);
1915	            return;
1916	        }
1917	        if (cloud_fn) {
1918	            cloud_fn(dev_id, payload);
1919	        }
1920	    };
1921	
1922	    if (queue_fn) {
1923	        queue_fn(dispatch);
1924	    } else {
1925	        dispatch();
1926	    }
1927	}
