1929	bool MoonrakerPrinterAgent::upload_gcode(const std::string& local_path,
1930	                                         const std::string& filename,
1931	                                         const std::string& base_url,
1932	                                         const std::string& api_key,
1933	                                         OnUpdateStatusFn   update_fn,
1934	                                         WasCancelledFn     cancel_fn)
1935	{
1936	    namespace fs = boost::filesystem;
1937	
1938	    // Validate file exists
1939	    fs::path source_path(local_path);
1940	    if (!fs::exists(source_path)) {
1941	        BOOST_LOG_TRIVIAL(error) << "MoonrakerPrinterAgent: File does not exist: " << local_path;
1942	        return false;
1943	    }
1944	
1945	    // Check file size
1946	    std::uintmax_t file_size = fs::file_size(source_path);
1947	    if (file_size > 1024 * 1024 * 1024) { // 1GB limit
1948	        BOOST_LOG_TRIVIAL(error) << "MoonrakerPrinterAgent: File too large: " << file_size << " bytes";
1949	        return false;
1950	    }
1951	
1952	    // Sanitize filename to prevent path traversal attacks
1953	    std::string safe_filename = sanitize_filename(filename);
1954	
1955	    bool        result = true;
1956	    std::string http_error;
1957	
1958	    // Use Http::form_add and Http::form_add_file
1959	    auto http = Http::post(join_url(base_url, "/server/files/upload"));
1960	    if (!api_key.empty()) {
1961	        http.header("X-Api-Key", api_key);
1962	    }
1963	    http.form_add("root", "gcodes") // Upload to gcodes directory
1964	        .form_add("print", "false") // Don't auto-start print
1965	        .form_add_file("file", source_path.string(), safe_filename)
1966	        .timeout_connect(5)
1967	        .timeout_max(300) // 5 minutes for large files
1968	        .on_complete([&](std::string body, unsigned status) {
1969	            (void) body;
1970	            (void) status;
1971	        })
1972	        .on_error([&](std::string body, std::string err, unsigned status) {
1973	            BOOST_LOG_TRIVIAL(error) << "MoonrakerPrinterAgent: Upload error: " << err << " HTTP " << status;
1974	            http_error = err;
1975	            result     = false;
1976	        })
1977	        .on_progress([&](Http::Progress progress, bool& cancel) {
1978	            // Check for cancellation via WasCancelledFn
1979	            if (cancel_fn && cancel_fn()) {
1980	                cancel = true;
1981	                result = false;
1982	                return;
1983	            }
1984	            // Report progress via OnUpdateStatusFn
1985	            if (update_fn && progress.ultotal > 0) {
1986	                int percent = static_cast<int>((progress.ulnow * 100) / progress.ultotal);
1987	                update_fn(PrintingStageUpload, percent, "Uploading...");
1988	            }
1989	        })
1990	        .perform_sync();
1991	
1992	    if (!result) {
1993	        BOOST_LOG_TRIVIAL(error) << "MoonrakerPrinterAgent: Upload failed: " << http_error;
1994	        return false;
1995	    }
1996	
1997	    return true;
1998	}
