2126	std::string MoonrakerPrinterAgent::normalize_base_url(std::string host, const std::string& port)
2127	{
2128	    boost::trim(host);
2129	    if (host.empty()) {
2130	        return "";
2131	    }
2132	
2133	    std::string value = host;
2134	    if (is_numeric(port) && value.find("://") == std::string::npos && value.find(':') == std::string::npos) {
2135	        value += ":" + port;
2136	    }
2137	
2138	    if (!boost::istarts_with(value, "http://") && !boost::istarts_with(value, "https://")) {
2139	        value = "http://" + value;
2140	    }
2141	
2142	    if (value.size() > 1 && value.back() == '/') {
2143	        value.pop_back();
2144	    }
2145	
2146	    return value;
2147	}
