2149	std::string MoonrakerPrinterAgent::join_url(const std::string& base_url, const std::string& path) const
2150	{
2151	    if (base_url.empty()) {
2152	        return "";
2153	    }
2154	    if (path.empty()) {
2155	        return base_url;
2156	    }
2157	    if (base_url.back() == '/' && path.front() == '/') {
2158	        return base_url.substr(0, base_url.size() - 1) + path;
2159	    }
2160	    if (base_url.back() != '/' && path.front() != '/') {
2161	        return base_url + "/" + path;
2162	    }
2163	    return base_url + path;
2164	}
