115	std::string model_text(const std::string& model, double nozzle)
116	{
117	    wxString text = wxString::FromUTF8(model);
118	    if (nozzle > 0.)
119	        text += (text.empty() ? wxString() : middle_dot()) + wxString::Format("%g mm", nozzle);
120	    return utf8(text);
