123	// "192.168.1.42:7125" for "http://192.168.1.42:7125/": the host and port as
124	// saved, without the scheme, a path, or any credentials written into it.
125	std::string host_address(const std::string& print_host)
126	{
127	    std::string address = print_host;
128	    if (const size_t scheme = address.find("://"); scheme != std::string::npos)
129	        address = address.substr(scheme + 3);
130	    address = address.substr(0, address.find('/'));
131	    if (const size_t at = address.rfind('@'); at != std::string::npos)
132	        address = address.substr(at + 1);
133	    return address.empty() ? print_host : address;
134	}
