142	// What the device reports about itself and its job. The connection line is
143	// the device's only when it has something verified to say; otherwise the
144	// card keeps what it had.
145	void describe_device(MachineObject& machine, PrinterEntry& printer)
146	{
147	    const bool printing        = machine_is_printing(machine);
148	    const bool connected       = PrinterSetup::has_recent_printer_data(machine);
149	    printer.state              = !connected ? PrinterState::Offline
150	                                 : printing ? PrinterState::Printing
151	                                            : PrinterState::Idle;
152	    printer.can_launch_monitor = connected;
153	    if (printing) {
154	        printer.progress_percent = machine.mc_print_percent;
155	        wxString status          = _L("Printing") + middle_dot() + wxString::Format("%d%%", machine.mc_print_percent);
156	        const wxString remaining = remaining_text(machine.mc_left_time);
157	        if (!remaining.empty())
158	            status += middle_dot() + remaining;
159	        printer.status_text = std::string(status.ToUTF8());
160	    }
161	    const std::string kind = machine.connection_type();
162	    if (connected) {
163	        printer.connection_state  = ConnectionState::Online;
164	        printer.connection_kind   = kind;
165	        printer.connection_text   = utf8(_L("Online") + middle_dot() + (kind == "lan" ? _L("LAN") : _L("Cloud")));
166	        printer.connection_action = "";
167	    } else if (PrinterSetup::has_verified_printer_connection(machine.get_dev_id())) {
168	        printer.connection_state  = ConnectionState::Offline;
169	        printer.connection_kind   = kind;
170	        printer.connection_text   = utf8(_L("Offline"));
171	        printer.connection_action = "reconnect";
172	    }
173	}
