201	std::vector<ProjectEntry> OrcaHomeBackend::recent_projects() const
202	{
203	    // Which project each printing machine is running, so a card can say so.
204	    // This is the only per-project status the codebase can answer today; the
205	    // rest is the file's own modified time until a project-state store exists.
206	    std::map<std::string, std::string> printing_by_stem;
207	    if (DeviceManager* devices = wxGetApp().getDeviceManager()) {
208	        for (const auto& entry : devices->get_my_machine_list()) {
209	            MachineObject* machine = entry.second;
210	            if (machine == nullptr)
211	                continue;
212	            if (machine_is_printing(*machine) && !machine->subtask_name.empty())
213	                printing_by_stem.emplace(machine->subtask_name, machine->get_dev_name());
214	        }
215	    }
216	
217	    std::vector<ProjectEntry>    projects;
218	    boost::property_tree::wptree recent;
219	    m_frame.get_recent_projects(recent, kThumbnailCap);
220	    size_t index = 0;
221	    for (const auto& node : recent) {
222	        const auto&  item = node.second;
223	        ProjectEntry project;
224	        project.id              = std::to_string(index++);
225	        const std::wstring path = item.get<std::wstring>(L"path", L"");
226	        project.name            = file_stem(path);
227	        project.path            = utf8(path);
228	        project.thumbnail_url   = utf8(item.get<std::wstring>(L"image", L""));
229	
230	        const auto printing = printing_by_stem.find(file_stem(path));
231	        if (printing != printing_by_stem.end()) {
232	            project.status_kind = ProjectStatusKind::Printing;
233	            project.status_text = std::string(
234	                wxString::Format(_L("Printing on %s"), wxString::FromUTF8(printing->second)).ToUTF8());
235	        } else {
236	            // Honest about what is known: nothing records whether this project
237	            // is sliced, so the card shows when it was last written, and says
238	            // which fact it is showing rather than dropping a bare timestamp
239	            // where the design puts a state.
240	            project.status_kind = ProjectStatusKind::Unknown;
241	            // The recent list stamps "YYYY-MM-DD HH:MM:SS"; a status line does
242	            // not need the second.
243	            wxString when = wxString(item.get<std::wstring>(L"time", L""));
244	            if (when.length() == 19 && when[16] == ':')
245	                when = when.Left(16);
246	            if (!when.empty())
247	                project.status_text = std::string(wxString::Format(_L("Edited %s"), when).ToUTF8());
248	        }
249	        projects.push_back(std::move(project));
250	    }
251	    return projects;
252	}
253	
254	std::vector<PrinterEntry> OrcaHomeBackend::printers() const
255	{
256	    std::map<std::string, MachineObject*> machines;
257	    if (DeviceManager* devices = wxGetApp().getDeviceManager()) {
258	        for (const auto& entry : devices->get_my_machine_list())
259	            if (entry.second != nullptr)
260	                machines.emplace(entry.first, entry.second);
261	    }
262	
263	    // What each connected device has loaded, read once for the whole rail.
264	    // A connected device with nothing loaded has an empty entry: it is the
265	    // printer saying so, and the card believes it over what was remembered.
266	    std::map<std::string, std::vector<SpoolEntry>> loaded;
267	    if (!machines.empty())
268	        for (const PrinterSetup::DiscoveredPrinter& device : PrinterSetup::discover_printers())
269	            if (device.connected) {
270	                auto& spools = loaded[device.stable_id];
271	                for (const PrinterSetup::DiscoveredPrinter::Spool& spool : device.spools)
272	                    spools.push_back(SpoolEntry{spool.material, spool.colour});
273	            }
274	
275	    // Every card says something about its connection; one with nothing
276	    // verified says so in words, and draws no dot.
277	    const auto settle_connection = [](PrinterEntry& printer) {
278	        if (printer.connection_state != ConnectionState::None)
279	            return;
280	        printer.connection_text   = utf8(_L("Not connected"));
281	        printer.connection_kind   = "";
282	        printer.connection_action = "";
283	    };
284	
285	    // The printers the person added, each with the device it stands for when
286	    // that device is here. The device's own reading of the nozzle wins: a
287	    // printer whose hardware was changed says so.
288	    std::vector<PrinterEntry> printers;
289	    std::set<std::string>     represented;
290	    for (const Printers::NamedPrinter& named : Printers::named_printers()) {
291	        PrinterEntry printer;
292	        printer.id                = kNamedPrefix + named.name;
293	        printer.name              = named.name;
294	        printer.kind              = PrinterKind::Named;
295	        printer.can_open_settings = true;
296	        printer.can_rename        = true;
297	        printer.can_remove        = true;
298	        std::string model;
299	        if (const auto* preset = wxGetApp().preset_bundle->printers.find_preset(named.name, false, true)) {
300	            model = model_name(preset->config.opt_string("printer_model"));
301	            // A print host's address is saved only once the host has answered
302	            // (or typed into Orca's own settings dialog, which is not tested:
303	            // an accepted gap). Nothing here says whether it answers now.
304	            const std::string host = preset->config.opt_string("print_host");
305	            if (!host.empty()) {
306	                printer.connection_state   = ConnectionState::Connected;
307	                printer.connection_kind    = "host";
308	                printer.address            = host_address(host);
309	                printer.connection_text    = utf8(_L("Connected") + middle_dot() + wxString::FromUTF8(printer.address));
310	                printer.can_launch_monitor = true;
311	            }
312	        }
313	        double nozzle = named.nozzle;
314	        if (const auto found = machines.find(named.device_id); !named.device_id.empty() && found != machines.end()) {
315	            describe_device(*found->second, printer);
316	            if (printer.can_launch_monitor) {
317	                wxGetApp().app_config->set("jusprin_verified_connections", named.device_id, "true");
318	                if (const double reported = reported_nozzle(*found->second); reported > 0.)
319	                    nozzle = reported;
320	            }
321	            represented.insert(named.device_id);
322	        } else if (PrinterSetup::has_verified_printer_connection(named.device_id)) {
323	            // Connected before, and the app has not heard of the device since.
324	            printer.connection_state  = ConnectionState::Offline;
325	            printer.connection_text   = utf8(_L("Offline"));
326	            printer.connection_action = "reconnect";
327	        }
328	        settle_connection(printer);
329	        printer.model_text = model_text(model, nozzle);
330	        // A connected printer says what it holds; otherwise the spools the
331	        // person described for it stand in.
332	        if (const auto held = loaded.find(named.device_id); !named.device_id.empty() && held != loaded.end())
333	            printer.spools = held->second;
334	        else if (m_spools != nullptr)
335	            for (const Workspace::Spool& spool : m_spools->spools_for(named.name))
336	                printer.spools.push_back(SpoolEntry{filament_type(spool.filament_preset), spool.colour});
337	        printers.push_back(std::move(printer));
338	    }
339	
340	    // Devices no named printer stands for. Their name and binding are the
341	    // device's, so renaming and removing them are upstream's device dialogs,
342	    // offered where upstream's device list offers them.
343	    for (const auto& [id, machine] : machines) {
344	        if (represented.count(id) > 0)
345	            continue;
346	        PrinterEntry printer;
347	        printer.id         = kDevicePrefix + id;
348	        printer.name       = machine->get_dev_name();
349	        printer.kind       = PrinterKind::Device;
350	        printer.can_rename = !machine->is_lan_mode_printer() && machine->is_online();
351	        printer.can_remove = !machine->is_lan_mode_printer();
352	        describe_device(*machine, printer);
353	        settle_connection(printer);
354	        printer.model_text = model_text(model_name({}, machine->printer_type), reported_nozzle(*machine));
355	        if (const auto held = loaded.find(id); held != loaded.end())
356	            printer.spools = held->second;
357	        printers.push_back(std::move(printer));
358	    }
359	    return printers;
360	}
