362	void OrcaHomeBackend::open_project(const std::string& project_id)
363	{
364	    if (project_id.empty())
365	        return;
366	    const size_t                 wanted = static_cast<size_t>(std::stoul(project_id));
367	    boost::property_tree::wptree recent;
368	    m_frame.get_recent_projects(recent, 0);
369	    size_t at = 0;
370	    for (const auto& node : recent) {
371	        if (at++ != wanted)
372	            continue;
373	        const wxString path(node.second.get<std::wstring>(L"path", L""));
374	        m_frame.open_recent_project(wanted, path);
375	        // Opening a project is a move to the workspace, but only if it opens.
376	        // open_recent_project queues the load behind can_load_project(), which
377	        // asks about unsaved changes and abandons the load when the answer is
378	        // Cancel. Queueing the move behind that lambda -- CallAfter is FIFO --
379	        // and confirming the project that is now open is the one that was
380	        // asked for keeps a cancelled open on Home instead of navigating out
381	        // from under it.
382	        m_frame.CallAfter([this, path] {
383	            Plater* plater = wxGetApp().plater();
384	            if (plater != nullptr && wxFileName(plater->get_project_filename()).SameAs(wxFileName(path)))
385	                m_frame.select_tab(size_t(MainFrame::tp3DEditor));
386	        });
387	        return;
388	    }
389	}
