402	void OrcaHomeBackend::import_model()
403	{
404	    Plater* plater = wxGetApp().plater();
405	    if (plater == nullptr)
406	        return;
407	    // add_model imports into the project that is open and runs its own modal
408	    // file dialog. It returns void, so the object count before and after is
409	    // what says whether anything arrived: cancelling the dialog leaves Home
410	    // where it was, as cancelling New does.
411	    const size_t before = plater->model().objects.size();
412	    plater->add_model();
413	    if (plater->model().objects.size() != before)
414	        m_frame.select_tab(size_t(MainFrame::tp3DEditor));
415	}
