417	void OrcaHomeBackend::launch_monitor(const std::string& printer_id)
418	{
419	    // A named printer is monitored through the device it stands for.
420	    std::string device_id = strip(printer_id, kDevicePrefix).value_or(std::string());
421	    if (const auto name = strip(printer_id, kNamedPrefix))
422	        for (const Printers::NamedPrinter& named : Printers::named_printers())
423	            if (named.name == *name)
424	                device_id = named.device_id;
425	    if (const auto name = strip(printer_id, kNamedPrefix); name && device_id.empty()) {
426	        open_printer_window(*name);
427	        return;
428	    }
429	    if (device_id.empty())
430	        return; // the card changed under the click; the refreshed rail says so
431	    // Upstream's own path to the Monitor, as the device popup and the
432	    // multi-machine page use. Selecting the tab and the machine by hand
433	    // instead left Home on screen: jump_to_monitor also guards on the Monitor
434	    // panel existing and selects the machine inside it. Upstream may still
435	    // decline the switch -- it vetoes the Monitor tab when the network plugin
436	    // is missing -- and that refusal is upstream's to make.
437	    m_frame.jump_to_monitor(device_id);
438	}
