440	void OrcaHomeBackend::open_printer_window(const std::string& name)
441	{
442	    const Preset* preset = wxGetApp().preset_bundle->printers.find_preset(name, false, true);
443	    if (preset == nullptr || preset->config.opt_string("print_host").empty())
444	        return; // the card changed under the click; the refreshed rail says so
445	    // One window per printer: a second click brings it back rather than
446	    // opening another beside it.
447	    if (auto open = m_printer_windows.find(name); open != m_printer_windows.end() && open->second) {
448	        open->second->Iconize(false);
449	        open->second->Raise();
450	        return;
451	    }
452	    m_printer_windows[name] = new PrinterWindow(name, preset->config);
453	}
