518	    if (plater == nullptr)
519	        return gone();
520	    if (const auto name = strip(printer_id, kNamedPrefix))
521	        return utf8(Printers::remove_named_printer(*plater, m_spools, *name));
522	    // Removing a device unbinds it from the account, through upstream's
523	    // dialog, which confirms and reports for itself, as the device list does.
524	    const std::string device_id = strip(printer_id, kDevicePrefix).value_or(std::string());
525	    MachineObject*    machine   = my_machine(device_id);
526	    if (machine == nullptr)
527	        return gone();
528	    UnBindMachineDialog dialog(plater);
529	    dialog.update_machine_info(machine);
530	    if (dialog.ShowModal() == wxID_OK)
531	        wxGetApp().getDeviceManager()->set_selected_machine("");
532	    return {};
533	}
