3	// The data behind the Home page, and the one function that turns it into the
4	// `state` payload of the jusprin-home-bridge protocol. No wx and no Orca types
5	// appear here, so the payload's shape is testable without a GUI: everything
6	// that needs a MainFrame, a PresetBundle, or the device layer lives in
7	// HomeHost, which fills these structs and hands them over.
8	//
9	// Optional fields are omitted from the JSON rather than sent as null or as an
10	// empty string: the page distinguishes "the host has nothing to say" from "the
11	// host says it is empty", and a serialised null would read as the latter.
12	
13	#include <nlohmann/json_fwd.hpp>
14	
15	#include <string>
16	#include <vector>
17	
18	namespace Slic3r { namespace GUI { namespace JusPrin { namespace Home {
19	
20	// Matches ProjectStatusKind in the page's protocol.ts. 'unknown' is what the
21	// host sends while nothing in the codebase records per-project slice state:
22	// the text carries what can be derived instead, and only 'printing' earns a
23	// colored dot on the card.
24	enum class ProjectStatusKind { Unknown, Draft, Sliced, Printing, Completed };
25	
26	const char* to_string(ProjectStatusKind kind);
27	
28	struct ProjectEntry
29	{
30	    std::string        id;
31	    std::string        name;
32	    std::string        path;
33	    std::string        thumbnail_url; // empty when the .3mf carries none
34	    ProjectStatusKind  status_kind{ProjectStatusKind::Unknown};
35	    std::string        status_text;
36	};
37	
38	// A spool the printer holds. Either field may be empty: a spool described
39	// without a colour is still a material the card can name.
40	struct SpoolEntry
41	{
42	    std::string material; // the filament type, such as "PLA"
43	    std::string colour;   // '#RRGGBB'
44	};
45	
46	enum class PrinterState { Idle, Printing, Offline };
47	
48	const char* to_string(PrinterState state);
49	
50	// What a card stands for, which decides how the page asks about its actions.
51	// A named printer is one the person added and names in JusPrin; the page
52	// confirms a rename or removal itself. A device is a Bambu printer on the
53	// network or the account that no named printer stands for; its rename and
54	// removal are Orca's own dialogs, which confirm for themselves.
55	enum class PrinterKind { Named, Device };
56	
57	const char* to_string(PrinterKind kind);
58	
59	// What a card's connection line and dot rest on, apart from its words.
60	// Online and Offline are a Bambu device's: data in the last 30 seconds, or
61	// verified before and silent now. Connected is a print host's: an address is
62	// saved. None is neither, and draws no dot.
63	enum class ConnectionState { None, Online, Offline, Connected };
64	
65	const char* to_string(ConnectionState state);
66	
67	struct PrinterEntry
68	{
69	    std::string             id;
70	    std::string             name;
71	    PrinterKind             kind{PrinterKind::Named};
72	    // The card's menu. An action the card cannot offer is sent as false and
73	    // shown disabled, so the menu keeps its shape.
74	    bool                    can_open_settings{false};
75	    bool                    can_rename{false};
76	    bool                    can_remove{false};
77	    PrinterState            state{PrinterState::Idle};
78	    std::string             status_text;
79	    // Below zero whenever there is no job to report; only a printing printer
80	    // sends a bar.
81	    int                     progress_percent{-1};
82	    // The Connection row: the finished line, the state it rests on, and the
83	    // transport -- "lan", "cloud", "host", or empty.
84	    ConnectionState         connection_state{ConnectionState::None};
85	    std::string             connection_text;
86	    std::string             connection_kind;
87	    std::string             connection_action; // "reconnect", or empty for no button
88	    // A print host's address as saved, without its scheme.
89	    std::string             address;
90	    // The Model row, "X1 Carbon · 0.4 mm"; empty when neither is known.
91	    std::string             model_text;
92	    // The Loaded row; empty when nothing is known to be loaded.
93	    std::vector<SpoolEntry> spools;
94	    bool                    can_launch_monitor{false};
95	};
