22	void HomeHost::send(const std::string& type, const json& payload, const std::string& correlation)
23	{
24	    json envelope{
25	        {"protocol", kProtocolName},
26	        {"version", kProtocolVersion},
27	        {"id", "h-" + std::to_string(m_next_id++)},
28	        {"type", type},
29	        {"payload", payload},
30	    };
31	    if (!correlation.empty())
32	        envelope["correlationId"] = correlation;
33	    ++m_sent;
34	    if (m_send)
35	        m_send(envelope.dump());
36	}
