47	std::vector<PrinterEntry> HomeHost::ordered_printers() const
48	{
49	    std::vector<PrinterEntry> printers = m_backend.printers();
50	    // Lead the column with it rather than wherever the backend's own
51	    // (alphabetical, not chronological) order puts it.
52	    const auto match = std::find_if(printers.begin(), printers.end(),
53	                                    [this](const PrinterEntry& printer) { return !m_added.empty() && printer.name == m_added; });
54	    if (match != printers.end())
55	        std::rotate(printers.begin(), match, match + 1);
56	    return printers;
57	}
