72	void HomeHost::send_state(Snapshot snapshot)
73	{
74	    const bool listed = std::any_of(snapshot.printers.begin(), snapshot.printers.end(),
75	                                    [this](const PrinterEntry& printer) { return !m_added.empty() && printer.name == m_added; });
76	    snapshot.highlight_printer = listed ? m_added : std::string();
