110	
111	void HomeHost::on_page_message(const std::string& text)
112	{
113	    ++m_received;
114	    json envelope;
115	    try {
116	        envelope = json::parse(text);
117	    } catch (const std::exception&) {
118	        // The page is the only writer on this transport and it sends JSON, so
119	        // a parse failure is a bug in the page rather than a state to recover
120	        // from. Dropping it keeps the bridge up; the page's own handshake
121	        // timeout is what reports a page that cannot talk at all.
122	        return;
123	    }
124	    if (envelope.value("protocol", std::string()) != kProtocolName)
125	        return; // another surface's traffic on the same transport
126	
127	    const std::string type        = envelope.value("type", std::string());
128	    const std::string correlation = envelope.value("id", std::string());
129	    const json        payload     = envelope.value("payload", json::object());
130	
131	    if (type == "hello") {
132	        const json versions    = payload.value("protocolVersions", json::array());
133	        const bool speaks_this = std::any_of(versions.begin(), versions.end(),
134	                                             [](const json& version) { return version == kProtocolVersion; });
135	        if (!speaks_this) {
136	            send("hello_reject", json{{"message", "This build speaks Home protocol version 1."}}, correlation);
137	            return;
138	        }
139	        m_connected = true;
140	        send("hello_ack", json{{"protocolVersion", kProtocolVersion}}, correlation);
141	        push_state();
142	        return;
143	    }
144	
145	    if (!m_connected)
146	        return; // nothing but hello is answered before the handshake
147	
148	    if (type == "state_request")
149	        push_state();
150	    else if (type == "open_project")
151	        m_backend.open_project(payload.value("id", std::string()));
152	    else if (type == "new_project")
153	        m_backend.new_project();
154	    else if (type == "import_project")
155	        m_backend.import_model();
156	    else if (type == "launch_monitor")
157	        m_backend.launch_monitor(payload.value("id", std::string()));
158	    else if (type == "add_printer") {
159	        m_backend.add_printer();
160	        push_state();
161	    }
162	    else if (type == "open_printer_settings" || type == "rename_printer" || type == "remove_printer" || type == "connect_printer") {
163	        const std::string id = payload.value("id", std::string());
164	        const std::string problem =
165	            type == "connect_printer"       ? m_backend.connect_printer(id)
166	            : type == "open_printer_settings" ? m_backend.open_printer_settings(id)
167	            : type == "rename_printer"      ? m_backend.rename_printer(id, payload.value("name", std::string()))
168	                                            : m_backend.remove_printer(id);
169	        if (!problem.empty())
170	            send("printer_error", json{{"id", id}, {"message", problem}}, correlation);
171	        // Each can change the rail, including when the person cancelled
172	        // halfway through an Orca prompt, so the page always gets it back.
173	        push_state();
174	    }
175	}
