46	HomeWebView::HomeWebView(wxWindow* parent, const ShellTheme& theme, MainFrame& frame, Workspace::SpoolStore* spools)
47	    : wxPanel(parent, wxID_ANY), m_theme(theme), m_live_timer(this)
48	{
49	    Bind(wxEVT_TIMER, &HomeWebView::on_live_tick, this, m_live_timer.GetId());
50	    m_backend = std::make_unique<OrcaHomeBackend>(frame, spools);
51	    m_host    = std::make_unique<HomeHost>(*m_backend, [this](const std::string& envelope) {
52	        if (m_webview == nullptr)
53	            return;
54	        wxString script = "window.__jusprinBridge && window.__jusprinBridge.deliver(";
55	        script += wxString::FromUTF8(envelope);
56	        script += ")";
57	        WebView::RunScript(m_webview, script);
58	    });
59	
60	    auto* sizer = new wxBoxSizer(wxVERTICAL);
61	    SetSizer(sizer);
62	
63	    m_error = new wxStaticText(this, wxID_ANY, wxEmptyString);
64	    m_error->Hide();
65	    sizer->Add(m_error, 0, wxALL, FromDIP(16));
66	
67	    apply_appearance(GUI_App::dark_mode());
68	
69	    const wxString url = home_page_url();
70	    if (url.empty()) {
71	        show_page_error(_L("The packaged Home page is missing from this build."));
72	        return;
73	    }
74	    m_webview = WebView::CreateWebView(this, url);
75	    if (m_webview == nullptr) {
76	        show_page_error(_L("The system web view could not be created."));
77	        return;
78	    }
79	    // The page fills the row; a panel the shell attaches sits beside it,
80	    // where the page's own printers column is.
81	    m_row = new wxBoxSizer(wxHORIZONTAL);
82	    m_row->Add(m_webview, 1, wxEXPAND);
83	    sizer->Add(m_row, 1, wxEXPAND);
84	    m_webview->Bind(wxEVT_WEBVIEW_SCRIPT_MESSAGE_RECEIVED, &HomeWebView::on_script_message, this);
85	    m_webview->Bind(wxEVT_WEBVIEW_ERROR, &HomeWebView::on_load_error, this);
86	    m_webview->Bind(wxEVT_WEBVIEW_NAVIGATING, [this](wxWebViewEvent& event) {
87	        // Every (re)load needs a fresh handshake before other traffic.
88	        m_host->reset_page();
89	        event.Skip();
90	    });
91	}
