1	import type { ConnectionState, PrinterInfo, SpoolInfo } from '../bridge/protocol';
2	import { MonitorGlyph, PrinterGlyph } from './Glyphs';
3	import { PrinterActions, PrinterMenu } from './PrinterMenu';
4	
5	// Every card has one shape: the header, the job while one runs, three fact
6	// rows in a fixed order, then the action. Each line rests on something the
7	// host verified, and a row with nothing to say is left out rather than filled
8	// with a placeholder.
9	//
10	// The dot means the connection and nothing else: green for Online and
11	// Connected, the warning colour for Offline, no dot for Not connected. A job
12	// is carried by the header's job text and the progress bar.
13	const DOT_LABEL: Record<ConnectionState, string | undefined> = {
14	  online: 'Online',
15	  connected: 'Connected',
16	  offline: 'Offline',
17	  none: undefined,
18	};
19	
20	// The distinct materials, in the order the spools hold them.
21	function materials(spools: SpoolInfo[]): string {
22	  const names: string[] = [];
23	  for (const spool of spools) {
24	    if (spool.material && !names.includes(spool.material)) names.push(spool.material);
25	  }
26	  return names.join(', ');
27	}
28	
29	export function PrinterCard({
30	  printer,
31	  otherNames,
32	  actions,
33	  onLaunchMonitor,
34	  highlighted,
35	}: {
36	  printer: PrinterInfo;
37	  otherNames: string[];
38	  actions: PrinterActions;
39	  onLaunchMonitor: (id: string) => void;
40	  // The printer a receipt just named: the card's own CSS animation draws
41	  // attention to it once and ends on its own -- no timer either side manages.
42	  highlighted?: boolean;
43	}) {
44	  const printing = printer.state === 'printing';
45	  const dotLabel = DOT_LABEL[printer.connectionState];
46	  // A LAN-only device offers none of the actions; a menu of disabled rows
47	  // would be a button that does nothing, so it has none.
48	  const hasActions = printer.canOpenSettings || printer.canRename || printer.canRemove;
49	  const loadedText = materials(printer.spools);
50	  const swatches = printer.spools.filter((spool) => spool.colour);
51	  // One label per kind of printer, not per state: a print host opens its own
52	  // page in a window of its own, a Bambu printer opens the monitor.
53	  const host = printer.connectionKind === 'host';
54	  return (
55	    <div className={highlighted ? 'printer-card printer-card-added' : 'printer-card'}>
56	      <div className="printer-head">
57	        <span className="printer-name-row">
58	          <PrinterGlyph />
59	          <span className="printer-name">{printer.name}</span>
60	        </span>
61	        <span className="printer-head-end">
62	          {dotLabel && (
63	            <span className={`status-dot ${printer.connectionState}`}>
64	              <span className="visually-hidden">{dotLabel}</span>
65	            </span>
66	          )}
67	          {hasActions && <PrinterMenu printer={printer} otherNames={otherNames} actions={actions} />}
68	        </span>
69	      </div>
70	      {/* The job heads the card under the name: the rail is too narrow to
71	          share the name's line with it without hiding the name. */}
72	      {printing && printer.statusText && <div className="printer-job">{printer.statusText}</div>}
73	      {printing && printer.progressPercent !== undefined && (
74	        <div
75	          className="printer-progress"
76	          role="progressbar"
77	          aria-valuenow={Math.round(printer.progressPercent)}
78	          aria-valuemin={0}
79	          aria-valuemax={100}
80	        >
81	          <span style={{ width: `${Math.max(0, Math.min(100, printer.progressPercent))}%` }} />
82	        </div>
83	      )}
84	      <dl className="printer-facts">
85	        {printer.connectionText && (
86	          <div className="printer-fact">
87	            <dt>Connection</dt>
88	            <dd>{printer.connectionText}</dd>
89	          </div>
90	        )}
91	        {printer.modelText && (
92	          <div className="printer-fact">
93	            <dt>Model</dt>
94	            <dd>{printer.modelText}</dd>
95	          </div>
96	        )}
97	        {(loadedText || swatches.length > 0) && (
98	          <div className="printer-fact">
99	            <dt>Loaded</dt>
100	            <dd className="printer-spools">
101	              {loadedText && <span className="printer-material">{loadedText}</span>}
102	              {swatches.map((spool, index) => (
103	                // The border is what keeps a black spool visible on the dark
104	                // card and a white one on the light card.
105	                <span key={`${spool.colour}-${index}`} className="spool-swatch" style={{ background: spool.colour }} />
106	              ))}
107	            </dd>
108	          </div>
109	        )}
110	      </dl>
111	      {printer.canLaunchMonitor ? (
112	        <button type="button" className="button-secondary launch-monitor" onClick={() => onLaunchMonitor(printer.id)}>
113	          <MonitorGlyph />
114	          {host ? 'Open printer window' : 'Launch monitor'}
115	        </button>
116	      ) : (
117	        printer.connectionAction === 'reconnect' &&
118	        actions.onConnect && (
119	          <button type="button" className="button-secondary launch-monitor" onClick={() => actions.onConnect?.(printer.id)}>
120	            Reconnect
121	          </button>
122	        )
123	      )}
124	    </div>
125	  );
126	}
