232	// A print host on a loopback port, for connection tests without hardware.
233	// Each request is held for `hold` (until the stand-in goes, when it is
234	// negative), then either answered as Moonraker's /server/info or hung up on.
235	class StandInHost
236	{
237	public:
238	    StandInHost(std::chrono::milliseconds hold, bool answer)
239	        : m_acceptor(m_io, boost::asio::ip::tcp::endpoint(boost::asio::ip::address_v4::loopback(), 0))
240	        , m_hold(hold)
241	        , m_answer(answer)
242	    {
243	        m_thread = std::thread([this] { serve(); });
244	    }
245	    ~StandInHost()
246	    {
247	        {
248	            std::lock_guard<std::mutex> lock(m_mutex);
249	            m_stopping = true;
250	            // A client can connect and never send a request -- a web view
251	            // opening spare connections does -- which would hold the serving
252	            // thread in its read for good.
253	            if (m_serving != nullptr) {
254	                boost::system::error_code ignored;
255	                m_serving->shutdown(boost::asio::ip::tcp::socket::shutdown_both, ignored);
256	            }
257	        }
258	        m_released.notify_all();
259	        // Wakes a blocking accept.
260	        boost::system::error_code ignored;
261	        boost::asio::ip::tcp::socket wake(m_io);
262	        wake.connect(m_acceptor.local_endpoint(), ignored);
263	        m_thread.join();
264	    }
265	    std::string address() const { return "http://127.0.0.1:" + std::to_string(m_acceptor.local_endpoint().port()); }
266	    int requests() const { return m_requests; }
267	
268	private:
269	    void serve()
270	    {
271	        for (;;) {
272	            boost::system::error_code error;
273	            boost::asio::ip::tcp::socket socket(m_io);
274	            m_acceptor.accept(socket, error);
275	            std::unique_lock<std::mutex> lock(m_mutex);
276	            if (m_stopping || error)
277	                return;
278	            ++m_requests;
279	            boost::asio::streambuf request;
280	            m_serving = &socket;
281	            lock.unlock();
282	            boost::asio::read_until(socket, request, "\r\n\r\n", error);
283	            lock.lock();
284	            m_serving = nullptr;
285	            if (m_hold.count() < 0)
286	                m_released.wait(lock, [this] { return m_stopping; });
287	            else
288	                m_released.wait_for(lock, m_hold, [this] { return m_stopping; });
289	            if (m_answer && !m_stopping) {
290	                const std::string body = R"({"result":{"klippy_state":"ready"}})";
291	                const std::string reply = "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: " +
292	                                          std::to_string(body.size()) + "\r\nConnection: close\r\n\r\n" + body;
293	                boost::asio::write(socket, boost::asio::buffer(reply), error);
294	            }
295	            socket.close(error);
296	        }
297	    }
298	
299	    boost::asio::io_context        m_io;
300	    boost::asio::ip::tcp::acceptor m_acceptor;
301	    std::chrono::milliseconds      m_hold;
302	    bool                           m_answer;
303	    std::atomic<int>               m_requests{0};
304	    std::mutex                     m_mutex;
305	    std::condition_variable        m_released;
306	    bool                           m_stopping{false};
307	    boost::asio::ip::tcp::socket*  m_serving{nullptr}; // the connection being read, under m_mutex
308	    std::thread                    m_thread;
309	};
