313	class ToolCallingAgent final : public Agent::IAgentService
314	{
315	public:
316	    ToolCallingAgent(std::string tool, nlohmann::json arguments) : m_tool(std::move(tool)), m_arguments(std::move(arguments)) {}
317	
318	    bool ready() const override { return true; }
319	    bool busy() const override { return m_active; }
320	    bool start(const Agent::AgentRequest& request) override
321	    {
322	        m_active = true;
323	        if (request.purpose != Agent::AgentRequest::Purpose::ConversationTitle && !m_called) {
324	            m_called = true;
325	            m_events.push_back(Agent::AgentEvent::tool_call({"call-1", Agent::ToolRequest{m_tool, m_arguments.dump()}, true}));
326	        } else {
327	            m_events.push_back(Agent::AgentEvent::delta("Checking."));
328	            m_events.push_back(Agent::AgentEvent::completed());
329	        }
330	        return true;
331	    }
332	    bool continue_after_tool(const Agent::AgentToolResult&) override
333	    {
334	        m_events.push_back(Agent::AgentEvent::delta("Checking."));
335	        m_events.push_back(Agent::AgentEvent::completed());
336	        return true;
337	    }
338	    void cancel() override
339	    {
340	        m_active = false;
341	        m_events.clear();
342	    }
343	    std::optional<Agent::AgentEvent> poll() override
344	    {
345	        if (m_events.empty())
346	            return std::nullopt;
347	        Agent::AgentEvent event = std::move(m_events.front());
348	        m_events.pop_front();
349	        if (event.kind == Agent::AgentEventKind::Completed || event.kind == Agent::AgentEventKind::Failed)
350	            m_active = false;
