1698	    // Connects `name` to a Moonraker host and waits up to `limit` for the
1699	    // outcome, counting a 100 ms timer's ticks meanwhile: a test run on the
1700	    // main thread stops the app, and the timer with it.
1701	    static HostOutcome connect_host_and_wait(PrinterSetup::OrcaPrinterBackend& backend, const std::string& name,
1702	                                             const std::string& address, std::chrono::seconds limit)
1703	    {
1704	        HostOutcome outcome;
1705	        wxTimer     timer;
1706	        timer.Bind(wxEVT_TIMER, [&outcome](wxTimerEvent&) { ++outcome.ticks; });
1707	        timer.Start(100);
1708	        const auto        start   = std::chrono::steady_clock::now();
1709	        const std::string problem = backend.connect_host(name, "moonraker", address, "");
1710	        outcome.state             = problem.empty() ? backend.connection(name).state : "refused: " + problem;
1711	        while (outcome.state == "connecting" && std::chrono::steady_clock::now() - start < limit) {
1712	            wxYield();
1713	            std::this_thread::sleep_for(std::chrono::milliseconds(10));
1714	            outcome.state = backend.connection(name).state;
1715	        }
1716	        timer.Stop();
1717	        outcome.took = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - start);
1718	        std::cout << "HARNESS host connect to " << address << ": " << outcome.state << " after " << outcome.took.count()
1719	                  << " ms, " << outcome.ticks << " timer ticks" << std::endl;
1720	        return outcome;
1721	    }
