1723	    // Waits, yielding to the app, until `done` or `limit` passes.
1724	    static bool wait_for(const std::function<bool()>& done, std::chrono::milliseconds limit)
1725	    {
1726	        const auto until = std::chrono::steady_clock::now() + limit;
1727	        while (!done()) {
1728	            if (std::chrono::steady_clock::now() > until)
1729	                return false;
1730	            wxYield();
1731	            std::this_thread::sleep_for(std::chrono::milliseconds(10));
1732	        }
1733	        return true;
1734	    }
