1883	            return nullptr;
1884	        Agent::AgentHost* host = panel->host();
1885	        host->set_agent(std::make_unique<ToolCallingAgent>(tool, arguments), Agent::AgentAvailability::Ready);
1886	        static int next = 0;
1887	        host->on_page_message(nlohmann::json{{"protocol", Agent::Protocol::kName},
1888	                                             {"version", Agent::Protocol::kVersion},
1889	                                             {"id", "call-" + std::to_string(++next)},
1890	                                             {"type", "user_message"},
1891	                                             {"payload", {{"clientMessageId", "call-c-" + std::to_string(next)}, {"text", "go on"}}}}
1892	                                  .dump());
1893	        const auto call = [host, tool]() -> const Agent::ToolActivity* {
