#pragma once

// What a Klipper printer's multi-filament unit reports as loaded, read from
// its Moonraker host, and how fresh that reading is. No wx and no Orca types:
// the parsing and the freshness rules are testable without a GUI or a
// printer. HostLaneReader does the network half and hands readings in here.
//
// The two sources and what they mean mirror OrcaSlicer's own
// MoonrakerPrinterAgent (fetch_moonraker_filament_data and
// fetch_hh_filament_info). That agent cannot be called for this: its readers
// are private, run on the calling thread, and write the shared device state;
// and its status stream is compiled out, so the device it feeds never counts
// as live. When upstream changes what those two functions accept, change the
// parsers here to match.

#include <chrono>
#include <map>
#include <mutex>
#include <optional>
#include <string>
#include <vector>

namespace Slic3r::GUI::JusPrin::Printers {

// One lane that holds filament. `colour` is "#RRGGBB", or empty when the lane
// reported none or one that is not a colour: a missing colour is not white.
struct HostLane
{
    int         index{0}; // the lane's tool number, from 0
    std::string material; // as the unit names it, such as "PLA"
    std::string colour;
};

// A reply read as one of the two sources. `unit` is false when the source
// shows no multi-filament unit; `loaded` then is empty.
struct UnitReport
{
    bool                  unit{false};
    std::vector<HostLane> loaded; // in lane order
};

// "#RRGGBB" for "#RRGGBB", "RRGGBB", "0xRRGGBB" or "RRGGBBAA"; empty otherwise.
std::string lane_colour(const std::string& raw);

// The body of GET /server/database/item?namespace=lane_data (AFC, and Happy
// Hare since February 2026). A unit is there when any entry has a lane
// number; a lane holds filament when it names a material. Nothing when the
// body is not that reply.
std::optional<UnitReport> parse_lane_data(const std::string& body);

// The body of GET /printer/objects/query?mmu (Happy Hare). A unit is there
// when `mmu` names a positive gate count; a gate holds filament when its
// status is above zero and it names a material. Nothing when the body is not
// that reply.
std::optional<UnitReport> parse_happy_hare(const std::string& body);

// What one attempt to read a host found.
struct HostReading
{
    // The host answered as Moonraker does.
    bool reached{false};
    // What is loaded, when the host said: empty for a unit with nothing loaded
    // and for a printer with no unit alike -- both are the printer saying
    // there is nothing to show. Absent when the host did not say.
    std::optional<std::vector<HostLane>> loaded;
};

enum class HostLink { Checking, Reachable, Unreachable };

struct HostStatus
{
    HostLink                             link{HostLink::Checking};
    // Only while Reachable, and only when the host said.
    std::optional<std::vector<HostLane>> loaded;
};

// A reading counts for as long as a Bambu printer's pushed data does
// (PrinterSetup::has_recent_printer_data): three missed polls.
inline constexpr std::chrono::seconds kHostReadingFresh{30};
inline constexpr std::chrono::seconds kHostPollInterval{10};

// The latest reading of each host, keyed by whatever identifies the host's
// settings: a changed address or key is a different host. Thread-safe: the
// readings arrive on worker threads.
class HostReadings
{
public:
    using Clock = std::chrono::steady_clock;

    // Reachable while an answer is fresh; Unreachable while the last attempt,
    // itself fresh, failed with no fresh answer; Checking otherwise -- never
    // asked, or asked too long ago to say.
    HostStatus status(const std::string& key, Clock::time_point now) const;

    // True, and the attempt recorded as started, when `key` is due another
    // read: none in flight and none started in the last poll interval.
    bool begin(const std::string& key, Clock::time_point now);
    void finish(const std::string& key, HostReading reading, Clock::time_point now);

    // The host answered some other request, such as a connection test. It
    // says nothing about what is loaded.
    void note_answered(const std::string& key, Clock::time_point now);

private:
    struct Entry
    {
        std::optional<Clock::time_point>     started;
        bool                                 in_flight{false};
        std::optional<Clock::time_point>     answered;  // last time the host answered
        std::optional<Clock::time_point>     failed;    // last attempt that got no answer
        std::optional<std::vector<HostLane>> loaded;    // from the last answer
    };

    mutable std::mutex           m_mutex;
    std::map<std::string, Entry> m_entries;
};

} // namespace Slic3r::GUI::JusPrin::Printers

#include "HostLanes.hpp"

#include <nlohmann/json.hpp>

#include <algorithm>
#include <cctype>

namespace Slic3r::GUI::JusPrin::Printers {

using nlohmann::json;

namespace {

// The field when it is a string, as upstream's safe_json_string reads it.
std::string string_field(const json& object, const char* key)
{
    const auto found = object.find(key);
    return found != object.end() && found->is_string() ? found->get<std::string>() : std::string();
}

std::string string_at(const json& list, std::size_t index)
{
    return index < list.size() && list[index].is_string() ? list[index].get<std::string>() : std::string();
}

int int_at(const json& list, std::size_t index)
{
    return index < list.size() && list[index].is_number() ? list[index].get<int>() : 0;
}

std::optional<json> parse(const std::string& body)
{
    json parsed = json::parse(body, nullptr, /*allow_exceptions=*/false, /*ignore_comments=*/true);
    if (parsed.is_discarded() || !parsed.is_object())
        return std::nullopt;
    return parsed;
}

} // namespace

std::string lane_colour(const std::string& raw)
{
    std::string value = raw;
    value.erase(value.begin(), std::find_if(value.begin(), value.end(), [](unsigned char c) { return !std::isspace(c); }));
    if (value.rfind("0x", 0) == 0 || value.rfind("0X", 0) == 0)
        value = value.substr(2);
    if (!value.empty() && value.front() == '#')
        value = value.substr(1);
    // Upstream keeps the hex digits and drops the rest, so "#None" is not a
    // colour; neither is anything that does not come to six or eight digits.
    std::string digits;
    for (const unsigned char c : value)
        if (std::isxdigit(c))
            digits.push_back(static_cast<char>(std::toupper(c)));
    if (digits.size() != 6 && digits.size() != 8)
        return {};
    return "#" + digits.substr(0, 6);
}

std::optional<UnitReport> parse_lane_data(const std::string& body)
{
    const auto reply = parse(body);
    if (!reply)
        return std::nullopt;
    const auto result = reply->find("result");
    if (result == reply->end() || !result->is_object())
        return std::nullopt;
    const auto value = result->find("value");
    if (value == result->end() || !value->is_object())
        return std::nullopt;

    UnitReport report;
    for (const auto& [key, lane] : value->items()) {
        if (!lane.is_object())
            continue;
        const std::string number = string_field(lane, "lane");
        int               index  = -1;
        try {
            index = number.empty() ? -1 : std::stoi(number);
        } catch (const std::exception&) {
            index = -1;
        }
        if (index < 0)
            continue;
        report.unit = true;
        const std::string material = string_field(lane, "material");
        if (!material.empty())
            report.loaded.push_back(HostLane{index, material, lane_colour(string_field(lane, "color"))});
    }
    std::sort(report.loaded.begin(), report.loaded.end(),
              [](const HostLane& a, const HostLane& b) { return a.index < b.index; });
    return report;
}

std::optional<UnitReport> parse_happy_hare(const std::string& body)
{
    const auto reply = parse(body);
    if (!reply)
        return std::nullopt;
    const auto result = reply->find("result");
    if (result == reply->end() || !result->is_object())
        return std::nullopt;
    const auto status = result->find("status");
    if (status == result->end() || !status->is_object())
        return std::nullopt;

    UnitReport report;
    const auto mmu = status->find("mmu");
    // Klipper leaves out an object it does not have, and Happy Hare not
    // installed leaves an empty one.
    if (mmu == status->end() || !mmu->is_object() || mmu->empty())
        return report;
    const auto gates = mmu->find("num_gates");
    if (gates == mmu->end() || !gates->is_number() || gates->get<int>() <= 0)
        return report;
    const auto list = [&mmu](const char* key) {
        const auto found = mmu->find(key);
        return found == mmu->end() ? json::array() : *found;
    };
    const json gate_status = list("gate_status"), gate_material = list("gate_material"), gate_color = list("gate_color"),
               gate_temperature = list("gate_temperature");
    if (!gate_status.is_array() || !gate_material.is_array() || !gate_color.is_array() || !gate_temperature.is_array())
        return report;

    report.unit = true;
    const int count = gates->get<int>();
    for (int gate = 0; gate < count; ++gate) {
        // -1 unknown, 0 empty, 1 or 2 available.
        if (int_at(gate_status, gate) <= 0)
            continue;
        const std::string material = string_at(gate_material, gate);
        if (!material.empty())
            report.loaded.push_back(HostLane{gate, material, lane_colour(string_at(gate_color, gate))});
    }
    return report;
}

HostStatus HostReadings::status(const std::string& key, Clock::time_point now) const
{
    std::lock_guard<std::mutex> lock(m_mutex);
    const auto found = m_entries.find(key);
    if (found == m_entries.end())
        return {};
    const Entry& entry    = found->second;
    const auto   is_fresh = [now](const std::optional<Clock::time_point>& at) { return at && now - *at < kHostReadingFresh; };
    HostStatus   status;
    if (is_fresh(entry.answered)) {
        status.link   = HostLink::Reachable;
        status.loaded = entry.loaded;
    } else if (is_fresh(entry.failed) && (!entry.answered || *entry.failed > *entry.answered)) {
        status.link = HostLink::Unreachable;
    }
    return status;
}

bool HostReadings::begin(const std::string& key, Clock::time_point now)
{
    std::lock_guard<std::mutex> lock(m_mutex);
    Entry& entry = m_entries[key];
    if (entry.in_flight || (entry.started && now - *entry.started < kHostPollInterval))
        return false;
    entry.in_flight = true;
    entry.started   = now;
    return true;
}

void HostReadings::finish(const std::string& key, HostReading reading, Clock::time_point now)
{
    std::lock_guard<std::mutex> lock(m_mutex);
    Entry& entry    = m_entries[key];
    entry.in_flight = false;
    if (reading.reached) {
        entry.answered = now;
        entry.loaded   = std::move(reading.loaded);
    } else {
        entry.failed = now;
    }
}

void HostReadings::note_answered(const std::string& key, Clock::time_point now)
{
    std::lock_guard<std::mutex> lock(m_mutex);
    m_entries[key].answered = now;
}

} // namespace Slic3r::GUI::JusPrin::Printers

